function exportTueCsv() {
    const rows = ['sku,on_hand,tue_demand,remaining,status',
        ..._tueData.map(r => `${r.sku},${r.on_hand},${r.tue_demand},${r.remaining},${r.status}`)];
    const blob = new Blob([rows.join('\n')], { type: 'text/csv' });
