function setSwapMode(mode) {
    swapMode = mode;
    document.getElementById('swap-pairs-panel').style.display = mode === 'manual' ? '' : 'none';
    document.getElementById('swap-matrix-panel').style.display = mode === 'matrix' ? '' : 'none';
