        setMascot('happy', `${data.total_orders} orders to swap`);
    } catch (e) {
        setMascot('alert', 'Preview failed');
        log('Preview error: ' + e.message, 'red');
    }
}

function renderSwapPreview(data) {
    const tbody = document.getElementById('swap-preview-body');
    const targets = data.all_targets || [];
    tbody.innerHTML = targets.map((t, i) => `
        <tr>
            <td>${i + 1}</td>

        const limitN = parseInt(document.getElementById('swap-limit')?.value || '0', 10);
        if (limitN > 0) {
            const targetsByPair = {};
            (swapPreviewData || []).forEach(t => {
                (targetsByPair[t.old_sku] = targetsByPair[t.old_sku] || []).push(t);
            });
            pairsWithGids.forEach(p => {
                const list = (targetsByPair[p.old_sku] || []).slice();
                list.sort((a, b) => parseInt(a.order_name.replace('#','')) - parseInt(b.order_name.replace('#','')));
                p.targets_override = list.slice(0, limitN).map(t => ({
                    order_gid: t.order_gid, order_name: t.order_name, qty: t.qty,
                }));
            });
        }

        // Stash for retry/backfill
        window._lastSwapShipTag = shipTag;
        window._lastSwapPairs = pairsWithGids;
        window._lastSwapBundleOnly = bundleOnly;
        window._lastSwapBoxSkuContains = boxSkuContains;

        const resp = await fetch('/api/swap/multi-execute', {
            method: 'POST',
