function ccFormatDate(isoStr) {
    if (!isoStr) return '';
    try {
        const d = new Date(isoStr);
        const now = new Date();
        const diffH = Math.round((d - now) / (1000 * 60 * 60));
        if (diffH <= 0) return 'now';
        if (diffH < 24) return `in ${diffH}h`;
        const diffD = Math.round(diffH / 24);
        if (diffD === 1) return 'tomorrow';
        return `in ${diffD}d`;
    } catch (e) {
        return '';
    }
}

