/* Matrix Commander — Dark FUI Theme */
:root {
  --bg: #0d1117;
  --bg2: #161b22;
  --bg3: #1c2128;
  --fg: #e6edf3;
  --fg2: #8b949e;
  --cyan: #00d4ff;
  --cyan-dim: #00d4ff33;
  --green: #3fb950;
  --red: #f85149;
  --yellow: #d29922;
  --orange: #db6d28;
  --border: #30363d;
  --font-data: 'DM Sans', sans-serif;
  --font-chrome: 'Space Mono', monospace;
  --font-num: 'Rajdhani', sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-data);
  font-size: 13px;
  min-height: 100vh;
  overflow-y: auto;
}

#app {
  max-width: 1400px;
  margin: 0 auto;
  padding: 12px 20px 60px;
}

/* Header */
#header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}
.header-left { display: flex; align-items: baseline; gap: 10px; }
.header-left h1 {
  font-family: var(--font-chrome);
  font-size: 16px;
  font-weight: 700;

  color: var(--cyan);
  letter-spacing: 2px;
}
.version {
  font-family: var(--font-chrome);
  font-size: 10px;
  color: var(--fg2);
}
.header-right { display: flex; gap: 16px; align-items: center; }
.config-group { display: flex; flex-direction: column; gap: 2px; }
.config-group label {
  font-family: var(--font-chrome);
  font-size: 9px;
  color: var(--fg2);
  text-transform: uppercase;
  letter-spacing: 1px;
}
.config-group select, .config-group input {
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  padding: 4px 8px;
  font-family: var(--font-chrome);
  font-size: 12px;
  border-radius: 3px;
}

/* Generate Section */
#generate-section { margin-bottom: 8px; }
.generate-row {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  margin-bottom: 8px;
}
.generate-row .config-group { flex: 1; }
.generate-row input[type="text"] {
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  padding: 6px 10px;
  font-family: var(--font-chrome);
  font-size: 13px;
  border-radius: 3px;
  width: 100%;
}
.or-divider {
  text-align: center;
  position: relative;
  margin: 12px 0;

}
.or-divider::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  border-top: 1px solid var(--border);
}
.or-divider span {
  background: var(--bg);
  padding: 0 12px;
  font-family: var(--font-chrome);
  font-size: 10px;
  color: var(--fg2);
  letter-spacing: 2px;
  position: relative;
}

/* Upload Section */
#upload-section {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}
.drop-zone {
  flex: 1;
  border: 2px dashed var(--border);
  border-radius: 6px;
  padding: 20px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
.drop-zone:hover, .drop-zone.dragover {
  border-color: var(--cyan);
  background: var(--cyan-dim);
}
.drop-zone.loaded {
  border-color: var(--green);
  border-style: solid;
}
.drop-zone.secondary { flex: 0.6; }
.drop-icon {

  font-family: var(--font-chrome);
  font-size: 24px;
  color: var(--fg2);
  line-height: 1;
}
.drop-label {
  font-family: var(--font-chrome);
  font-size: 10px;
  color: var(--fg2);
  margin-top: 6px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.drop-file {
  font-family: var(--font-data);
  font-size: 12px;
  color: var(--cyan);
  margin-top: 4px;
  word-break: break-all;
}

/* Buttons */
.btn {
  font-family: var(--font-chrome);
  font-size: 11px;
  font-weight: 600;
  padding: 8px 20px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg3);
  color: var(--fg);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: all 0.15s;
}
.btn:hover { border-color: var(--cyan); color: var(--cyan); }
.btn:disabled { opacity: 0.3; cursor: not-allowed; }
.btn.primary {
  background: var(--cyan);
  color: var(--bg);
  border-color: var(--cyan);
}
.btn.primary:hover { background: #33ddff; }
.btn.primary:disabled { background: var(--bg3); color: var(--fg2); border-color: var(--border); }
.btn.danger { border-color: var(--red); color: var(--red); }
.btn.danger:hover { background: var(--red); color: var(--bg); }
.file-btn { display: inline-block; }

/* Panels */

.panel {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 16px;
  margin-bottom: 12px;
}
.panel.hidden { display: none; }
.panel h2 {
  font-family: var(--font-chrome);
  font-size: 11px;
  font-weight: 700;
  color: var(--cyan);
  letter-spacing: 2px;
  margin-bottom: 12px;
}

/* Stats Row */
.stats-row { display: flex; gap: 24px; margin-bottom: 12px; }
.stat { display: flex; flex-direction: column; align-items: center; }
.stat-num {
  font-family: var(--font-num);
  font-size: 28px;
  font-weight: 600;
  color: var(--fg);
  line-height: 1;
}
.stat-label {
  font-family: var(--font-chrome);
  font-size: 9px;
  color: var(--fg2);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Checks List */
.check-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  border-bottom: 1px solid var(--border);
}
.check-item:last-child { border-bottom: none; }
.check-icon {
  font-family: var(--font-chrome);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;

  min-width: 36px;
  text-align: center;
}
.check-icon.pass { background: #3fb95022; color: var(--green); }
.check-icon.fail { background: #f8514922; color: var(--red); }
.check-name {
  font-family: var(--font-chrome);
  font-size: 11px;
  color: var(--fg);
  flex: 1;
}
.check-msg {
  font-family: var(--font-data);
  font-size: 11px;
  color: var(--fg2);
}
.check-details {
  font-size: 11px;
  color: var(--fg2);
  padding-left: 50px;
  margin-top: 2px;
}

/* Inventory Table */
.table-container { overflow-x: auto; max-height: 400px; overflow-y: auto; }
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
th {
  font-family: var(--font-chrome);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--fg2);
  padding: 6px 10px;
  text-align: left;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg2);
}
td {
  padding: 4px 10px;
  border-bottom: 1px solid #21262d;
  font-family: var(--font-data);
}
td.num {

  font-family: var(--font-num);
  font-size: 13px;
  font-weight: 500;
  text-align: right;
}
tr.short td { color: var(--red); }
tr.low td { color: var(--yellow); }
tr.ok td { color: var(--fg); }
td.status-badge {
  font-family: var(--font-chrome);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
}

/* Swap Cards */
.swap-card {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 12px;
  margin-bottom: 8px;
}
.swap-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.swap-sku {
  font-family: var(--font-chrome);
  font-size: 12px;
  font-weight: 700;
  color: var(--red);
}
.swap-shortage {
  font-family: var(--font-num);
  font-size: 14px;
  color: var(--red);
}
.swap-name { font-size: 11px; color: var(--fg2); margin-bottom: 6px; }
.swap-candidates { display: flex; gap: 6px; flex-wrap: wrap; }
.swap-candidate {
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 3px;
  font-family: var(--font-chrome);
  font-size: 10px;
  cursor: pointer;
  transition: all 0.15s;

}
.swap-candidate:hover { border-color: var(--green); color: var(--green); }
.swap-candidate.recommended { border-color: var(--cyan); color: var(--cyan); }
.swap-candidate .surplus {
  font-family: var(--font-num);
  font-size: 11px;
  color: var(--fg2);
  margin-left: 4px;
}
.no-candidates {
  font-family: var(--font-chrome);
  font-size: 10px;
  color: var(--yellow);
}

/* Inventory Controls */
.inventory-controls { display: flex; gap: 8px; margin-bottom: 12px; }

/* Action Buttons */
.action-buttons { display: flex; gap: 12px; margin-bottom: 12px; }
#finalResult {
  font-family: var(--font-chrome);
  font-size: 12px;
  color: var(--green);
  padding: 8px 0;
}

/* Status Bar */
#statusBar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--bg3);
  border-top: 1px solid var(--border);
  padding: 6px 20px;
  font-family: var(--font-chrome);
  font-size: 10px;
  color: var(--fg2);
  z-index: 100;
}

/* Sync Controls */
.sync-controls {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.sync-controls .config-group { flex: 0 1 auto; }
.sync-controls input[type="text"],
.sync-controls select {
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  padding: 6px 10px;
  font-family: var(--font-chrome);
  font-size: 12px;
  border-radius: 3px;
}

/* Sync Results */
.sync-results { margin-bottom: 8px; }
.sync-stats-row {
  display: flex;
  gap: 20px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.sync-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.sync-stat-num {
  font-family: var(--font-num);
  font-size: 24px;
  font-weight: 600;
  line-height: 1;
}
.sync-stat-label {
  font-family: var(--font-chrome);
  font-size: 9px;
  color: var(--fg2);
  text-transform: uppercase;
  letter-spacing: 1px;
}
.sync-stat-num.updated { color: var(--green); }
.sync-stat-num.skipped { color: var(--fg2); }
.sync-stat-num.gift { color: var(--cyan); }
.sync-stat-num.duplicate { color: var(--yellow); }
.sync-stat-num.error { color: var(--red); }
.sync-stat-num.matched { color: var(--fg); }

/* Sync Errors */
.sync-errors details {
  margin-top: 8px;
  background: var(--bg3);
  border: 1px solid var(--border);

  border-radius: 4px;
  padding: 8px 12px;
}
.sync-errors summary {
  font-family: var(--font-chrome);
  font-size: 11px;
  color: var(--red);
  cursor: pointer;
  letter-spacing: 1px;
}
.sync-errors .error-item {
  font-size: 11px;
  color: var(--fg2);
  padding: 4px 0;
  border-bottom: 1px solid #21262d;
}
.sync-errors .error-item:last-child { border-bottom: none; }
.sync-errors .error-order {
  font-family: var(--font-chrome);
  color: var(--fg);
  margin-right: 8px;
}

/* Loading spinner */
.spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid var(--fg2);
  border-top-color: var(--cyan);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin-right: 6px;
  vertical-align: middle;
}
@keyframes spin { to { transform: rotate(360deg); } }

{% extends "base.html" %}
{% block title %}Login{% endblock %}
{% block content %}
<section class="login">
  <h2>Sign in</h2>
  <form method="post">
    <label>Password
      <input type="password" name="password" autocomplete="current-password" required autofocus>
    </label>
    <button type="submit">Enter</button>
  </form>
</section>
{% endblock %}

/* Cut Order — base styles. */
:root {
  --bg: #f7f7f7;
  --fg: #1f2328;
  --accent: #1f6feb;
  --accent-dark: #144cb0;
  --card: #fff;
  --muted: #6b6e74;
  --err: #b3261e;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Calibri", "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--fg);
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 24px;
  background: #1f2328;
  color: #fff;
}

.brand h1 { margin: 0; font-size: 1.4rem; color: #fff; }

.logout button {
  background: transparent;
  border: 1px solid #fff;
  color: #fff;
  padding: 4px 10px;
  cursor: pointer;
}

main {
  max-width: 960px;
  margin: 24px auto;
  padding: 0 16px;
}

.login, .run {
  background: var(--card);
  padding: 24px;
  border-radius: 8px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.08);

}

.login form { display: flex; flex-direction: column; gap: 12px; max-width: 320px; }
.login input { padding: 8px; font-size: 1rem; }
.login button, .run button {
  padding: 8px 16px;
  background: var(--accent);
  border: 1px solid var(--accent-dark);
  color: #fff;
  cursor: pointer;
  font-weight: bold;
}

.flash { list-style: none; padding: 0; max-width: 960px; margin: 12px auto; }
.flash-error { background: #fde0de; color: var(--err); padding: 8px 12px; border-radius: 4px; }

.muted { color: var(--muted); }
code { background: #eef0f3; padding: 2px 6px; border-radius: 3px; }

/* Run form */
.meta { background: #eef0f3; padding: 10px 14px; border-radius: 6px; margin-bottom: 16px; }
.meta div { margin: 2px 0; }

fieldset { margin: 16px 0; padding: 12px 16px; border: 1px solid #d8dbe0; border-radius: 6px; }
fieldset legend { padding: 0 6px; font-weight: bold; color: var(--accent-dark); }

.grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 16px; }
.row { display: flex; align-items: center; gap: 8px; }
.row label { flex: 1; font-family: monospace; font-size: 0.9rem; }
.row input[type="number"] { width: 70px; padding: 4px 6px; }
.row input[type="text"] { flex: 1; padding: 4px 6px; }

.lock {
  background: transparent;
  border: 1px solid #d8dbe0;
  padding: 2px 6px;
  border-radius: 4px;
  cursor: pointer;
  opacity: 0.4;
}
.lock.locked { opacity: 1; background: #fff4c2; border-color: var(--accent-dark); }
.lock:hover { opacity: 0.8; }

.remove {
  background: transparent; border: none; cursor: pointer;
  color: var(--err); font-weight: bold; font-size: 1.2rem;
}

.actions { margin-top: 16px; display: flex; align-items: center; gap: 12px; }
#runStatus, #ratiosStatus { font-style: italic; }

.result { margin-top: 24px; padding: 16px; background: #d8f5d8; border-radius: 6px; }
.result a { font-size: 1.1rem; font-weight: bold; color: var(--accent-dark); }
.result pre { background: #fff; padding: 10px; border-radius: 4px; overflow-x: auto; font-size: 0.85rem; }

/* ═══════════════════════════════════════════════════════════════════
   Fulfillment Planner — FUI Theme (Charcoal + Cyan)
   Inspired by AppyHour // Cold Chain Control
   ═══════════════════════════════════════════════════════════════════ */

:root {
    --bg:          #0a0a0d;
    --bg2:         #131316;
    --bg3:         #1c1c20;
    --surface:     #161619;
    --surface2:    #1e1e22;
    --border:      #2a2a30;
    --border-bright: #3a3a42;
    --accent:      #00d4ff;
    --accent2:     #0099cc;
    --accent-glow: rgba(0,212,255,0.12);
    --fg:          #c8d4dc;
    --fg2:         #6a7a88;
    --fg3:         #4a5a68;
    --green:       #00e676;
    --green-dim:   rgba(0,230,118,0.08);
    --red:         #ff3b5c;
    --red-rgb:     255,59,92;
    --green-rgb:   0,230,118;
    --red-dim:     rgba(255,59,92,0.10);
    --yellow:      #d4960a;
    --yellow-dim:  rgba(212,150,10,0.08);
    --blue:        #60a5fa;
    --orange:      #ff8800;
    --warm:        #e8a940;
    --rw-bar-ok:   #e8a940;
    --rw-bar-tight: #d4960a;
    --rw-bar-shortage: #ff3b5c;
    --cheese:      #d4a830;
    --cheese-light: #e0be50;
    --cheese-dark: #a07818;
    --cheese-hole: #b8901c;
    --radius:      4px;
    --radius-sm:   3px;
    --shadow:      0 2px 8px rgba(0,0,0,0.3);
    --shadow-lg:   0 8px 32px rgba(0,0,0,0.45);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
    font-family: 'DM Sans', 'Segoe UI', system-ui, sans-serif;
    background: var(--bg);
    color: var(--fg);
    overflow: hidden;

    height: 100vh;
    font-size: 13px;
    -webkit-font-smoothing: antialiased;
}

/* ── Sidebar layout ────────────────────────────────────────────────── */

#app {
    display: flex;
    height: 100vh;
    position: relative;
    z-index: 1;
}

#sidebar {
    width: 180px;
    min-width: 180px;
    height: 100vh;
    background: var(--bg2);
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    z-index: 10;
    overflow-y: auto;
    overflow-x: hidden;
}

.sb-logo {
    padding: 16px 14px 12px;
    border-bottom: 1px solid var(--border);
}
.sb-logo-text {
    font-family: 'Space Mono', monospace;
    font-size: 15px;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 1px;
    display: block;
}
.sb-logo-sub {
    font-family: 'DM Sans', sans-serif;
    font-size: 10px;
    color: var(--fg2);
    letter-spacing: 0.5px;
}

.sb-section {
    padding: 10px 0 4px;
}
.sb-section-label {

    font-family: 'Space Mono', monospace;
    font-size: 9px;
    font-weight: 600;
    color: var(--fg3);
    letter-spacing: 1.5px;
    padding: 0 14px 6px;
}

.sb-nav {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 7px 14px;
    border: none;
    background: none;
    color: var(--fg2);
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    cursor: pointer;
    transition: background 0.12s, color 0.12s;
    text-align: left;
    border-left: 2px solid transparent;
}
.sb-nav:hover {
    background: rgba(0,212,255,0.05);
    color: var(--fg);
}
.sb-nav.active {
    background: rgba(0,212,255,0.08);
    color: var(--accent);
    border-left-color: var(--accent);
}
.sb-icon {
    font-size: 14px;
    width: 18px;
    text-align: center;
    flex-shrink: 0;
}

.sb-footer {
    margin-top: auto;
    padding: 10px 14px;
    border-top: 1px solid var(--border);
    font-size: 10px;
    color: var(--fg3);
}

#main-area {
    flex: 1;

    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-width: 0;
}

/* Subtle grid background */
body::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image:
        linear-gradient(rgba(0,212,255,0.04) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0,212,255,0.04) 1px, transparent 1px);
    background-size: 48px 48px;
    pointer-events: none;
    z-index: 0;
}

/* Animated background canvas */
#bg-canvas {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    z-index: 0;
    pointer-events: none;
    opacity: 1;
    transform: translateZ(0);
    will-change: transform;
}

/* ── Layout ──────────────────────────────────────────────────────── */
#app {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-rows: auto auto 1fr;
    height: 100vh;
    gap: 0;
}

/* ── Toolbar ─────────────────────────────────────────────────────── */
#toolbar {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 6px 12px;
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    flex-wrap: wrap;

    flex-shrink: 0;
}

#toolbar .title {
    font-family: 'Rajdhani', sans-serif;
    font-size: 22px;
    font-weight: 700;
    color: var(--accent);
    margin-right: 12px;
    display: none;
    letter-spacing: 1px;
}

.btn {
    font-family: 'Space Mono', 'Consolas', monospace;
    font-size: 11px;
    font-weight: 400;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 6px 14px;
    border-radius: var(--radius-sm);
    border: 1px solid transparent;
    cursor: pointer;
    transition: all 0.2s;
    color: var(--fg);
    background: transparent;
    white-space: nowrap;
    will-change: transform;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0); }

.btn-green { color: var(--warm); border-color: var(--warm); }
.btn-green:hover { background: var(--warm); color: var(--bg); }
.btn-blue { color: var(--accent); border-color: var(--accent2); }
.btn-blue:hover { background: var(--accent); color: var(--bg); }
.btn-accent { color: #b894f0; border-color: rgba(184,148,240,0.4); }
.btn-accent:hover { background: #b894f0; color: var(--bg); }
.btn-yellow { color: var(--orange); border-color: rgba(255,136,0,0.4); }
.btn-yellow:hover { background: var(--orange); color: var(--bg); }
.btn-orange { color: #ff6600; border-color: rgba(255,102,0,0.4); }
.btn-orange:hover { background: #ff6600; color: var(--bg); }
.btn-red { color: var(--red); border-color: rgba(255,59,92,0.4); }
.btn-red:hover { background: var(--red); color: var(--bg); }
.btn-dim { color: var(--fg2); border-color: var(--border); }
.btn-dim:hover { border-color: var(--border-bright); color: var(--fg); }

.toolbar-sep {
    width: 1px;
    height: 24px;

    background: var(--border);
    margin: 0 6px;
}

/* Demand mode button */
.btn-demand-mode {
    border: 1px solid var(--accent) !important;
    font-family: 'Space Mono', monospace;
    font-size: 9px;
}

/* More tools overflow dropdown */
.toolbar-more {
    position: relative;
}
.toolbar-more-menu {
    display: none;
    position: absolute;
    top: calc(100% + 6px);
    right: 0;
    background: var(--bg2);
    border: 1px solid var(--border-bright);
    border-radius: var(--radius);
    box-shadow: var(--shadow-lg);
    z-index: 200;
    min-width: 140px;
    padding: 4px;
    flex-direction: column;
    gap: 2px;
}
.toolbar-more-menu.open {
    display: flex;
}
.toolbar-more-menu .btn {
    width: 100%;
    text-align: left;
    padding: 7px 12px;
    border-radius: var(--radius-sm);
}
.toolbar-more-menu .btn:hover {
    background: var(--surface2);
    transform: none;
}

#score {
    margin-left: auto;
    font-family: 'Rajdhani', sans-serif;
    font-size: 20px;
    font-weight: 600;
    color: var(--accent);

    min-width: 80px;
    text-align: right;
    transition: transform 0.3s;
}
#score.pop { animation: scorePop 0.4s ease; }

#last-sync {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    color: var(--fg3);
    margin-left: 12px;
    letter-spacing: 1px;
    text-transform: uppercase;
}

@keyframes scorePop {
    0% { transform: scale(1); }
    50% { transform: scale(1.5); color: #fff; }
    100% { transform: scale(1); }
}

/* ── Banner ──────────────────────────────────────────────────────── */
#banner {
    display: none;
    background: linear-gradient(90deg, var(--green-dim), rgba(0,230,118,0.12), var(--green-dim));
    text-align: center;
    padding: 10px;
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    font-weight: 400;
    color: var(--green);
    letter-spacing: 3px;
    text-transform: uppercase;
}
#banner.visible { display: block; animation: bannerFlash 1.5s ease; }

@keyframes bannerFlash {
    0%, 100% { background: linear-gradient(90deg, var(--green-dim), rgba(0,230,118,0.12), var(--green-dim)); }
    33% { background: linear-gradient(90deg, rgba(0,230,118,0.15), rgba(0,230,118,0.25), rgba(0,230,118,0.15)); color: white; }
}

/* ── Main content ────────────────────────────────────────────────── */
#content {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 14px;
    padding: 14px 16px;
    overflow: hidden;
    min-height: 0;
}

/* ── Widget panels ───────────────────────────────────────────────── */
.panel {
    position: relative;
    background: var(--surface);
    border-radius: var(--radius);
    border: 1px solid var(--border);
    box-shadow: var(--shadow);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: border-color 0.2s;
    animation: fadeIn 0.5s ease-out both;
    contain: layout style;
}

.panel:hover { border-color: var(--border-bright); }

/* Accent glow line on top of panels */
.panel::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent), transparent);
    opacity: 0.2;
    z-index: 1;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* Staggered panel entry */
.panel:nth-child(1) { animation-delay: 0ms; }
.panel:nth-child(2) { animation-delay: 40ms; }
.panel:nth-child(3) { animation-delay: 80ms; }
.panel:nth-child(4) { animation-delay: 120ms; }
.panel:nth-child(5) { animation-delay: 160ms; }
.panel:nth-child(6) { animation-delay: 200ms; }

.panel-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 14px;
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    font-family: 'Space Mono', monospace;

    font-weight: 700;
    font-size: 9px;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 2px;
    flex-shrink: 0;
}

.panel-header .icon { font-size: 14px; }
.panel-body { flex: 1; overflow-y: auto; padding: 6px; min-height: 0; }

/* ── Left column ─────────────────────────────────────────────────── */
#left-col {
    display: flex;
    flex-direction: column;
    gap: 12px;
    overflow: hidden;
    min-height: 0;
}

/* ── Mascot speech bubble (floating, follows Kori) ─────────────── */
#mascot-speech {
    position: fixed;
    z-index: 51;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    max-width: 200px;
    min-width: 120px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.3s ease;
}
#mascot-speech.visible { opacity: 1; }
#mascot-speech-inner { padding: 8px 12px; }
#mascot-speech-tail {
    position: absolute;
    bottom: -6px;
    left: 20px;
    width: 12px;
    height: 12px;
    background: var(--surface);
    border-right: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    transform: rotate(45deg);
}
#mascot-msg {
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    font-weight: 400;

    color: var(--fg);
    line-height: 1.4;
}
#mascot-state {
    font-family: 'Space Mono', monospace;
    font-size: 8px;
    color: var(--fg3);
    margin-top: 2px;
    text-transform: uppercase;
    letter-spacing: 2px;
}

/* ── Free-roaming mascot (Wedge) — Kawaii style ─────────────── */
#mascot {
    position: fixed;
    width: 85px;
    height: 115px;
    z-index: 50;
    pointer-events: auto;
    cursor: pointer;
    filter: drop-shadow(0 2px 6px rgba(0,0,0,0.4))
           drop-shadow(0 8px 16px rgba(0,0,0,0.25));
    transition: transform 0.08s linear;
    will-change: transform;
    transform: translateZ(0);
}
#mascot.flipped { transform: scaleX(-1); }
#mascot.pet { animation: petBounce 0.3s ease; }

/* Eye styling */
.mascot-eye-iris { transition: cx 0.05s, cy 0.05s; }
.mascot-eye-pupil { fill: #1A1A1A; opacity: 0; }

/* Brows (hidden by default, shown for some expressions) */
.mascot-brow {
    stroke: #3D2B0A; stroke-width: 3;
    stroke-linecap: round; fill: none;
}

/* Blush */
.mascot-blush { opacity: 0.55; transition: opacity 0.3s; }

/* Speed lines */
#mascot-speed-lines { transition: opacity 0.2s; }

/* Extra indicator */
#mascot-extra { font-family: 'Rajdhani', sans-serif; font-weight: 700; }

/* Pet bounce */
@keyframes petBounce {

    0%, 100% { transform: scale(1); }
    30% { transform: scale(1.15) translateY(-8px); }
    60% { transform: scale(0.95); }
}

/* Idle bob */
@keyframes idleBob {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    25%      { transform: translateY(-3px) rotate(1deg); }
    75%      { transform: translateY(-1px) rotate(-1deg); }
}
#mascot.idle #mascot-body-group { animation: idleBob 2.5s ease-in-out infinite; }

/* Happy bounce */
@keyframes happyBounce {
    0%, 100% { transform: translateY(0); }
    25% { transform: translateY(-8px); }
    50% { transform: translateY(0); }
    75% { transform: translateY(-4px); }
}
#mascot.happy #mascot-body-group,
#mascot.celebrate #mascot-body-group { animation: happyBounce 0.7s ease; }

/* Worried shake */
@keyframes worriedShake {
    0%, 100% { transform: translateX(0); }
    20% { transform: translateX(-3px); }
    40% { transform: translateX(3px); }
    60% { transform: translateX(-2px); }
    80% { transform: translateX(2px); }
}
#mascot.worried #mascot-body-group { animation: worriedShake 0.5s ease; }

/* Loading wobble */
@keyframes loadingWobble {
    0%, 100% { transform: rotate(0deg); }
    25%      { transform: rotate(2deg); }
    75%      { transform: rotate(-2deg); }
}
#mascot.loading #mascot-body-group { animation: loadingWobble 0.8s ease-in-out infinite; }

/* ── Assignment table (widget) ───────────────────────────────────── */
#assign-panel {
    flex: 0 0 auto;
}

.assign-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;

    font-size: 12px;
}

.assign-table th {
    text-align: left;
    padding: 6px 8px;
    background: var(--bg2);
    color: var(--accent);
    font-family: 'Space Mono', monospace;
    font-weight: 400;
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 2px;
    position: sticky;
    top: 0;
    z-index: 1;
}

.assign-table td {
    padding: 5px 8px;
    border-bottom: 1px solid rgba(255,255,255,0.025);
    cursor: pointer;
    transition: background 0.12s;
}

.assign-table tr:hover td { background: rgba(0,212,255,0.03); }

.assign-table tr.drop-hover td {
    background: rgba(0,230,118,0.08) !important;
    outline: 1px dashed var(--green);
    outline-offset: -1px;
}

.assign-table .cheese-cell {
    font-weight: 500;
    font-family: 'DM Sans', sans-serif;
    font-size: 11px;
    letter-spacing: 0.5px;
    white-space: nowrap;
}
.assign-table .pr-cheese { color: var(--accent); }
.assign-table .ec-cheese { color: #b894f0; }
.assign-table .qty-cell { color: var(--fg3); text-align: right; font-size: 11px; white-space: nowrap; }
.assign-table .split-cell { color: var(--orange); font-size: 10px; white-space: nowrap; }
.assign-table .constraint-ok { color: var(--green); font-size: 11px; }
.assign-table .constraint-bad { color: var(--red); font-weight: 700; font-size: 11px; }

/* Flash on assignment */
.assign-table tr.flash-success td { animation: flashGreen 0.6s ease; }
.assign-table tr.flash-fail td { animation: flashRed 0.6s ease; }

@keyframes flashGreen {
    0%, 100% { background: transparent; }
    50% { background: rgba(0,230,118,0.1); }
}
@keyframes flashRed {
    0%, 100% { background: transparent; }
    50% { background: rgba(255,59,92,0.1); }
}

/* ── Global Extras panel ─────────────────────────────────────────── */
#extras-panel { flex: 0 0 auto; }
.extras-slot-cell { font-weight: 600; font-size: 11px; }
.extras-type-cell { color: var(--fg3); font-size: 10px; }
.extras-sku-cell { cursor: pointer; font-weight: 500; font-size: 11px; }
.extras-sku-cell:hover { text-decoration: underline; }
.extras-sku-cell.assigned { color: var(--green); }
.extras-sku-cell.unassigned { color: var(--red); }

/* ── Shelf life widget ───────────────────────────────────────────── */
#shelf-panel { flex-shrink: 0; max-height: 150px; }
.shelf-table { width: 100%; border-collapse: collapse; font-size: 11px; }
.shelf-table th {
    text-align: left; padding: 4px 8px; background: var(--bg2);
    color: var(--accent); font-family: 'Space Mono', monospace;
    font-size: 9px; text-transform: uppercase; letter-spacing: 2px;
    position: sticky; top: 0;
}
.shelf-table td { padding: 4px 8px; border-bottom: 1px solid rgba(255,255,255,0.025); }
.shelf-expired { color: var(--red); }
.shelf-expiring { color: var(--yellow); }
.shelf-fresh { color: var(--green); }

/* ── Right column ────────────────────────────────────────────────── */
#right-col {
    display: flex;
    flex-direction: column;
    gap: 12px;
    overflow: hidden;
    min-height: 0;
}

/* ── Shortage progress bar ───────────────────────────────────────── */
#progress-panel {
    flex-shrink: 0;
    padding: 10px 16px;
    gap: 6px;
}
#progress-panel::before { opacity: 0; }
.progress-header {

    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
}
.progress-label {
    font-family: 'Space Mono', monospace;
    font-size: 12px;
    font-weight: 700;
    color: var(--fg2);
    text-transform: uppercase;
    letter-spacing: 2px;
}
.progress-value {
    font-family: 'Rajdhani', sans-serif;
    font-size: 18px;
    font-weight: 600;
    color: var(--accent);
}
.progress-track {
    height: 4px;
    background: var(--bg3);
    border-radius: 2px;
    overflow: hidden;
}
.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--red), var(--yellow), var(--green));
    border-radius: 2px;
    transition: width 0.6s ease;
}
.progress-detail {
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    color: var(--fg3);
    margin-top: 4px;
    letter-spacing: 0.5px;
}

/* ── Summary widgets ─────────────────────────────────────────────── */
#summary-bar {
    display: flex;
    gap: 12px;
    flex-shrink: 0;
}

.stat-widget {
    flex: 1;
    background: var(--surface);
    border: 1px solid var(--border);

    border-radius: var(--radius);
    padding: 10px 16px;
    display: flex;
    align-items: center;
    gap: 12px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s;
}

.stat-widget:hover { border-color: var(--border-bright); }

/* Accent line on stat widgets too */
.stat-widget::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent), transparent);
    opacity: 0.15;
}

.stat-widget .stat-icon {
    font-size: 18px;
    width: 36px;
    height: 36px;
    border-radius: var(--radius);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}
.stat-widget .stat-icon.icon-skus { background: var(--accent-glow); }
.stat-widget .stat-icon.icon-units { background: var(--yellow-dim); }
.stat-widget .stat-icon.icon-shortages { background: var(--red-dim); }

.stat-widget .stat-info { flex: 1; min-width: 0; }
.stat-widget .stat-label {
    font-family: 'Space Mono', monospace;
    font-size: 12px;
    font-weight: 700;
    color: var(--fg2);
    text-transform: uppercase;
    letter-spacing: 2px;
}
.stat-widget .stat-value {
    font-family: 'Rajdhani', sans-serif;
    font-size: 24px;
    font-weight: 600;
    color: var(--fg);

    line-height: 1.2;
}

/* ── Tabs ────────────────────────────────────────────────────────── */
#net-panel { flex: 1; min-height: 0; }

.tab-bar {
    display: flex;
    gap: 0;
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    flex-shrink: 0;
}

.tab-btn {
    font-family: 'Space Mono', monospace;
    padding: 8px 18px;
    background: transparent;
    border: none;
    color: var(--fg3);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    transition: all 0.15s;
    text-transform: uppercase;
}
.tab-btn:hover { color: var(--fg2); background: rgba(0,212,255,0.02); }
.tab-btn.active {
    color: var(--accent);
    border-bottom-color: var(--accent);
    background: rgba(0,212,255,0.03);
}

.tab-content { display: none; flex: 1; overflow: hidden; min-height: 0; }
.tab-content.active { display: flex; flex-direction: column; }

/* ── Filter bar ──────────────────────────────────────────────────── */
.filter-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    flex-shrink: 0;
}

.filter-bar label {
    font-family: 'Space Mono', monospace;
    font-size: 9px;

    color: var(--accent);
    letter-spacing: 2px;
    text-transform: uppercase;
}

.filter-select {
    background: var(--surface2);
    color: var(--fg);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    padding: 4px 8px;
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    outline: none;
    transition: border-color 0.2s, box-shadow 0.2s;
}
.filter-select:focus {
    border-color: var(--accent2);
    box-shadow: 0 0 0 2px var(--accent-glow);
}

/* ── NET table ───────────────────────────────────────────────────── */
.net-table-wrap { flex: 1; overflow-y: auto; min-height: 0; }

.net-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 12px;
}

.net-table th {
    text-align: left;
    padding: 8px 8px;
    background: var(--surface2);
    color: var(--accent);
    font-family: 'Space Mono', monospace;
    font-weight: 400;
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 2px;
    cursor: pointer;
    user-select: none;
    position: sticky;
    top: 0;
    z-index: 1;
    border-bottom: 1px solid var(--border);
    transition: color 0.15s;
    white-space: nowrap;
}

.net-table th:hover { color: var(--fg); background: rgba(0,212,255,0.04); }
.net-table th.sorted { color: var(--accent); }

.net-table td {
    padding: 5px 8px;
    border-bottom: 1px solid rgba(255,255,255,0.02);
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    color: var(--fg);
}

.net-table td.sku-cell {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    font-weight: 400;
    cursor: grab;
}
.net-table td.sku-cell:active { cursor: grabbing; }

.net-table td.num {
    text-align: right;
    padding-right: 20%;
    font-family: 'Rajdhani', sans-serif;
    font-weight: 500;
    font-size: 14px;
}
.net-table th.num {
    text-align: right;
    padding-right: 20%;
}

/* Risk row — subtle left border instead of full row color */
.net-table tr.shortage td:first-child { box-shadow: inset 3px 0 0 var(--red); }
.net-table tr.tight td:first-child    { box-shadow: inset 3px 0 0 var(--yellow); }
.net-table tr.surplus td:first-child   { box-shadow: inset 3px 0 0 var(--green); }

.net-table tr.shortage td { color: var(--fg); }
.net-table tr.shortage td.net-cell { color: var(--red); font-weight: 600; }
.net-table tr.tight td { color: var(--fg); }
.net-table tr.tight td.net-cell { color: var(--yellow); }
.net-table tr.ok td { color: var(--fg); }
.net-table tr.surplus td { color: var(--fg); }
.net-table tr.surplus td.net-cell { color: var(--green); }
.net-table tr.no-demand td { color: var(--fg3); }

.net-table tr:hover td { background: rgba(0,212,255,0.03); }
.net-table tr:nth-child(even) td { background: rgba(255,255,255,0.01); }
.net-table tr:nth-child(even):hover td { background: rgba(0,212,255,0.04); }

.net-table .status-badge {

    display: inline-block;
    padding: 2px 6px;
    border-radius: 2px;
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    font-weight: 400;
    text-transform: uppercase;
    letter-spacing: 1px;
    border: 1px solid;
}
.status-SHORTAGE { color: var(--red); border-color: var(--red); background: var(--red-dim); }
.status-TIGHT { color: var(--yellow); border-color: var(--yellow); background: var(--yellow-dim); }
.status-OK { color: var(--fg3); border-color: var(--border); background: transparent; }
.status-SURPLUS { color: var(--green); border-color: var(--green); background: var(--green-dim); }
.status-NO-DEMAND, .status-NO\ DEMAND { color: var(--fg3); border-color: transparent; background: transparent; }
.status-PLAN-PO { color: var(--red); border-color: var(--red); background: var(--red-dim); }
.status-MFG { color: var(--blue); border-color: var(--blue); background: rgba(96,165,250,0.08); }

/* ── Log widget ──────────────────────────────────────────────────── */
#log-panel {
    flex-shrink: 0;
    max-height: 160px;
}

#log {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    line-height: 1.6;
    padding: 4px;
    letter-spacing: 0.5px;
}

.log-entry {
    padding: 2px 6px;
    border-left: 2px solid transparent;
    transition: background 0.15s ease;
}
.log-entry:hover { background: rgba(255,255,255,0.03); }
.log-entry:has(.log-green) { border-left-color: var(--green); background: color-mix(in srgb, var(--green) 6%, transparent); }
.log-entry:has(.log-red) { border-left-color: var(--red); background: color-mix(in srgb, var(--red) 8%, transparent); }
.log-entry:has(.log-yellow) { border-left-color: var(--yellow); background: color-mix(in srgb, var(--yellow) 7%, transparent); }
.log-entry:has(.log-cyan) { border-left-color: var(--accent); background: color-mix(in srgb, var(--accent) 6%, transparent); }
.log-time {
    color: var(--fg3);
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    background: rgba(255,255,255,0.04);
    padding: 1px 5px;
    border-radius: 3px;
    margin-right: 4px;

}
.log-green { color: var(--green); }
.log-red { color: var(--red); }
.log-yellow { color: var(--yellow); }
.log-cyan { color: var(--accent); }

/* ── Drag ghost ──────────────────────────────────────────────────── */
#drag-ghost {
    position: fixed;
    pointer-events: none;
    z-index: 9999;
    background: var(--accent);
    color: var(--bg);
    font-family: 'Space Mono', monospace;
    font-weight: 700;
    font-size: 10px;
    letter-spacing: 1px;
    padding: 5px 10px;
    border-radius: var(--radius-sm);
    box-shadow: 0 0 16px var(--accent-glow), var(--shadow-lg);
    display: none;
}

/* ── Pop-up score text ───────────────────────────────────────────── */
.score-pop {
    position: fixed;
    pointer-events: none;
    z-index: 9998;
    font-family: 'Rajdhani', sans-serif;
    font-size: 24px;
    font-weight: 700;
    color: var(--accent);
    text-shadow: 0 0 12px var(--accent-glow);
    animation: floatUp 1s ease-out forwards;
}

@keyframes floatUp {
    0% { opacity: 1; transform: translateY(0) scale(1); }
    100% { opacity: 0; transform: translateY(-70px) scale(1.4); }
}

/* ── Picker sidebar ──────────────────────────────────────────────── */
#picker-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 100;
}
#picker-overlay.visible { display: flex; }

#picker-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(2px);
}

#picker-panel {
    position: absolute;
    right: 0; top: 0; bottom: 0;
    width: 360px;
    background: var(--surface);
    border-left: 1px solid var(--border);
    box-shadow: var(--shadow-lg);
    display: flex;
    flex-direction: column;
    animation: slideIn 0.2s ease;
}

@keyframes slideIn {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
}

#picker-panel .picker-header {
    padding: 16px;
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
}
#picker-panel .picker-title {
    font-family: 'Rajdhani', sans-serif;
    font-size: 18px;
    font-weight: 600;
    color: var(--accent);
    letter-spacing: 1px;
}
#picker-panel .picker-hint {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    color: var(--fg3);
    margin-top: 4px;
    letter-spacing: 1px;
}

#picker-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
}

.picker-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: all 0.15s;
    border: 1px solid transparent;
}
.picker-item:hover { background: rgba(0,212,255,0.04); border-color: var(--border); }
.picker-item.blocked { opacity: 0.4; }
.picker-item.blocked:hover { background: var(--red-dim); }

.picker-item .pi-sku {
    font-family: 'Space Mono', monospace;
    font-weight: 400;
    font-size: 10px;
    min-width: 100px;
    letter-spacing: 0.5px;
}
.picker-item .pi-qty {
    color: var(--fg3);
    font-family: 'Rajdhani', sans-serif;
    font-size: 14px;
    min-width: 60px;
    text-align: right;
}
.picker-item .pi-constraint { font-size: 10px; font-weight: 600; }
.picker-item .pi-ok { color: var(--green); }
.picker-item .pi-bad { color: var(--red); }

#picker-footer {
    padding: 12px 16px;
    background: var(--bg2);
    border-top: 1px solid var(--border);
    display: flex;
    gap: 8px;
    justify-content: flex-end;
}

/* ── Substitution overlay ────────────────────────────────────────── */
#subs-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 100;
}
#subs-overlay.visible { display: flex; }
#subs-backdrop {

    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(2px);
}
#subs-panel {
    position: absolute;
    right: 0; top: 0; bottom: 0;
    width: 440px;
    background: var(--surface);
    border-left: 1px solid var(--border);
    box-shadow: var(--shadow-lg);
    display: flex;
    flex-direction: column;
    animation: slideIn 0.2s ease;
}
#subs-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
}
.sub-shortage {
    margin-bottom: 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
}
.sub-shortage-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    background: var(--red-dim);
    border-bottom: 1px solid var(--border);
}
.sub-shortage-sku {
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    font-weight: 700;
    color: var(--red);
}
.sub-shortage-info {
    font-family: 'Rajdhani', sans-serif;
    font-size: 13px;
    color: var(--fg2);
    margin-left: auto;
}
.sub-item {
    display: flex;
    align-items: center;

    gap: 8px;
    padding: 6px 12px;
    border-bottom: 1px solid rgba(255,255,255,0.02);
    transition: background 0.12s;
}
.sub-item:hover { background: rgba(0,212,255,0.03); }
.sub-item-sku {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    min-width: 100px;
    color: var(--fg);
}
.sub-item-info {
    font-family: 'Rajdhani', sans-serif;
    font-size: 13px;
    color: var(--fg2);
    flex: 1;
}
.sub-item-tag {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    padding: 1px 6px;
    border-radius: 2px;
    border: 1px solid;
}
.sub-full { color: var(--green); border-color: var(--green); background: var(--green-dim); }
.sub-partial { color: var(--yellow); border-color: var(--yellow); background: var(--yellow-dim); }
.sub-none {
    padding: 8px 12px;
    font-size: 11px;
    color: var(--fg3);
    font-style: italic;
}

/* ── Confetti ────────────────────────────────────────────────────── */
.confetti {
    position: fixed;
    pointer-events: none;
    z-index: 9997;
    font-size: 18px;
    animation: confettiFall 2s ease-out forwards;
}

@keyframes confettiFall {
    0% { opacity: 1; transform: translateY(-20px) rotate(0deg); }
    100% { opacity: 0; transform: translateY(100vh) rotate(720deg); }
}

/* ── Scrollbar ───────────────────────────────────────────────────── */
::-webkit-scrollbar { width: 5px; height: 5px; }

::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--accent2); }

/* ── Loading shimmer ─────────────────────────────────────────────── */
@keyframes shimmer {
    0%   { background-position: -200px 0; }
    100% { background-position: 200px 0; }
}

.loading-shimmer {
    background: linear-gradient(90deg,
        var(--surface) 0%,
        rgba(0,212,255,0.04) 50%,
        var(--surface) 100%);
    background-size: 200px 100%;
    animation: shimmer 1.5s infinite;
}

/* ── Headroom mini bars ─────────────────────────────────────────── */
.headroom-bar {
    display: inline-flex;
    align-items: center;
    position: relative;
    width: 60px;
    height: 14px;
    background: var(--bg3);
    border-radius: 2px;
    overflow: hidden;
    font-family: 'Rajdhani', sans-serif;
    font-size: 10px;
    font-weight: 600;
    vertical-align: middle;
}
.headroom-fill {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    border-radius: 2px;
    transition: width 0.4s ease;
    opacity: 0.7;
}
.headroom-label {
    position: relative;
    z-index: 1;
    width: 100%;
    text-align: center;
    color: var(--fg);
    text-shadow: 0 0 4px rgba(0,0,0,0.8);
    font-size: 9px;
    letter-spacing: 0.5px;

}
.headroom-neg .headroom-label { color: var(--red); }

/* ── NET cell dynamic color intensity ───────────────────────────── */
.net-cell-critical { color: #ff1744 !important; font-weight: 700; text-shadow: 0 0 6px rgba(255,23,68,0.3); }
.net-cell-bad { color: var(--red) !important; font-weight: 600; }
.net-cell-warn { color: var(--yellow) !important; }
.net-cell-ok { color: var(--fg2) !important; }
.net-cell-good { color: var(--green) !important; }
.net-cell-great { color: #69f0ae !important; font-weight: 600; text-shadow: 0 0 6px rgba(105,240,174,0.2); }

/* ── Click-to-copy feedback ─────────────────────────────────────── */
.sku-cell.copied {
    color: var(--accent) !important;
    transition: color 0.2s;
}
.copy-toast {
    position: fixed;
    z-index: 9999;
    background: var(--accent);
    color: var(--bg);
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    padding: 3px 8px;
    border-radius: 3px;
    pointer-events: none;
    animation: toastFade 0.8s ease forwards;
}
@keyframes toastFade {
    0% { opacity: 1; transform: translateY(0); }
    100% { opacity: 0; transform: translateY(-16px); }
}

/* ── Stat counter animation ─────────────────────────────────────── */
.stat-value.counting {
    transition: none;
}

/* ── Keyboard nav highlight ─────────────────────────────────────── */
.net-table tr.kb-focus td {
    background: rgba(0,212,255,0.06) !important;
    outline: 1px solid rgba(0,212,255,0.2);
    outline-offset: -1px;
}

/* ── Shortage screen flash ──────────────────────────────────────── */
@keyframes screenFlash {
    0% { opacity: 0.15; }
    100% { opacity: 0; }
}

.screen-flash {
    position: fixed;
    inset: 0;
    background: var(--red);
    pointer-events: none;
    z-index: 200;
    animation: screenFlash 0.5s ease-out forwards;
}

/* ── View toggle buttons ───────────────────────────────────────── */
.view-btn {
    opacity: 0.5;
    border: 1px solid var(--border) !important;
    background: var(--bg3) !important;
    color: var(--fg2) !important;
}
.view-btn.active {
    opacity: 1;
    background: var(--accent-glow) !important;
    color: var(--accent) !important;
    border-color: var(--accent2) !important;
}

/* ══════════════════════════════════════════════════════════════════
   CALENDAR VIEW
   ══════════════════════════════════════════════════════════════════ */
#calendar-view {
    padding: 12px 20px;
    overflow-y: auto;
    height: calc(100vh - 52px);
}

/* Calendar summary bar */
#calendar-header {
    margin-bottom: 14px;
}
.cal-summary {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}
.cal-summary-item {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 10px 18px;
    min-width: 140px;
}
.cal-summary-label {
    display: block;

    font-size: 10px;
    color: var(--fg3);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 4px;
}
.cal-summary-value {
    display: block;
    font-family: 'Space Mono', monospace;
    font-size: 20px;
    font-weight: 700;
    color: var(--fg);
}

/* Calendar grid — weeks as rows, days as columns */
#calendar-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.cal-week {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
}
.cal-week-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 14px;
    background: var(--bg3);
    border-bottom: 1px solid var(--border);
}
.cal-week-label {
    font-family: 'Rajdhani', sans-serif;
    font-size: 15px;
    font-weight: 600;
    color: var(--accent);
}
.cal-week-stats {
    font-size: 11px;
    color: var(--fg2);
}
.cal-week-stats .shortage-badge {
    color: var(--red);
    font-weight: 600;
}

.cal-days {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 1px;
    background: var(--border);
}
.cal-day {
    background: var(--surface);
    min-height: 110px;
    padding: 6px 8px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    transition: background 0.15s;
}
.cal-day:hover {
    background: var(--surface2);
}
.cal-day.is-today {
    background: rgba(0,212,255,0.04);
    box-shadow: inset 0 2px 0 var(--accent);
}
.cal-day.is-past {
    opacity: 0.45;
}
.cal-day-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2px;
}
.cal-day-dow {
    font-size: 10px;
    text-transform: uppercase;
    color: var(--fg3);
    letter-spacing: 0.5px;
}
.cal-day-num {
    font-family: 'Space Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    color: var(--fg2);
}
.cal-day.is-today .cal-day-num {
    color: var(--accent);
}

/* Task chips */
.cal-task {
    font-size: 10px;

    padding: 3px 6px;
    border-radius: 3px;
    cursor: pointer;
    transition: transform 0.1s, box-shadow 0.1s;
    line-height: 1.3;
    border-left: 3px solid transparent;
}
.cal-task:hover {
    transform: translateX(2px);
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}
.cal-task-title {
    font-weight: 600;
    display: block;
}
.cal-task-detail {
    color: var(--fg3);
    font-size: 9px;
    display: block;
    margin-top: 1px;
}

/* Task type colors */
.cal-task-PO {
    background: rgba(96,165,250,0.12);
    border-left-color: var(--blue);
    color: var(--blue);
}
.cal-task-MFG {
    background: rgba(255,136,0,0.12);
    border-left-color: var(--orange);
    color: var(--orange);
}
.cal-task-CROSSDOCK {
    background: rgba(0,230,118,0.12);
    border-left-color: var(--green);
    color: var(--green);
}
.cal-task-FULFILL {
    background: rgba(0,212,255,0.10);
    border-left-color: var(--accent);
    color: var(--accent);
}
.cal-task-FULFILL.has-shortages {
    background: rgba(255,59,92,0.10);
    border-left-color: var(--red);
    color: var(--red);
}
.cal-task-INVENTORY {
    background: rgba(200,212,220,0.06);

    border-left-color: var(--fg3);
    color: var(--fg2);
}

/* Detail drawers */
.cal-drawer {
    display: none;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    margin-top: 12px;
    overflow: hidden;
}
.cal-drawer.visible {
    display: block;
}
.cal-drawer-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 14px;
    background: var(--bg3);
    border-bottom: 1px solid var(--border);
}
.cal-drawer-title {
    font-family: 'Rajdhani', sans-serif;
    font-size: 15px;
    font-weight: 600;
    color: var(--accent);
}
.cal-drawer-body {
    padding: 10px 14px;
    max-height: 300px;
    overflow-y: auto;
}
.cal-drawer-body table {
    width: 100%;
    border-collapse: collapse;
}
.cal-drawer-body th,
.cal-drawer-body td {
    padding: 5px 10px;
    text-align: left;
    font-size: 12px;
    border-bottom: 1px solid var(--border);
}
.cal-drawer-body th {
    color: var(--fg3);
    font-size: 10px;
    text-transform: uppercase;

    letter-spacing: 0.5px;
}
.cal-drawer-body td.num,
.cal-drawer-body th.num {
    text-align: right;
    font-family: 'Space Mono', monospace;
    padding-right: 10px;
}
.cal-drawer-body tr.shortage td {
    color: var(--red);
}
.btn-sm {
    font-size: 10px;
    padding: 3px 10px;
}

/* ── Invoices View ──────────────────────────────────────────────── */
#invoices-view {
    padding: 12px 20px;
    overflow-y: auto;
    height: calc(100vh - 52px);
}
#invoices-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 12px;
}
.inv-actions {
    display: flex;
    gap: 6px;
    align-items: center;
}
#inv-list-panel {
    display: flex;
    flex-direction: column;
    max-height: calc(100vh - 220px);
    overflow: hidden;
}
.inv-pending { color: var(--yellow); }

/* Invoice status badges */
.inv-status-matched {
    background: var(--green-dim);
    color: var(--green);
    border: 1px solid rgba(0,230,118,0.25);
}
.inv-status-partial {

    background: var(--yellow-dim);
    color: var(--yellow);
    border: 1px solid rgba(212,150,10,0.25);
}
.inv-status-pending {
    background: rgba(255,136,0,0.08);
    color: var(--orange);
    border: 1px solid rgba(255,136,0,0.25);
}
.inv-status-error {
    background: var(--red-dim);
    color: var(--red);
    border: 1px solid rgba(255,59,92,0.25);
}

/* Unmatched product — clickable dashed style */
.inv-unmatched {
    display: inline-block;
    padding: 2px 8px;
    border: 1px dashed var(--orange);
    border-radius: 2px;
    color: var(--orange);
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    letter-spacing: 0.5px;
    cursor: pointer;
    transition: background 0.15s;
}
.inv-unmatched:hover {
    background: rgba(255,136,0,0.12);
}

/* Cost bar for analytics */
.inv-cost-bar {
    height: 6px;
    background: linear-gradient(90deg, var(--accent2), var(--accent));
    border-radius: 3px;
    min-width: 2px;
}

/* SKU mapper overlay — reuses picker pattern */
#inv-sku-mapper {
    position: fixed;
    inset: 0;
    z-index: 200;
    display: flex;
    align-items: center;
    justify-content: center;
}
#inv-mapper-backdrop {

    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.6);
}
#inv-mapper-panel {
    position: relative;
    width: 400px;
    max-height: 70vh;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    display: flex;
    flex-direction: column;
    box-shadow: var(--shadow-lg);
}
#inv-mapper-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
    max-height: 50vh;
}
/* Override large padding-right in drawer/detail tables */
#inv-detail-body .num,
#inv-cost-body .num {
    padding-right: 10px !important;
}

.inv-mapper-section {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    color: var(--fg3);
    letter-spacing: 1px;
    padding: 8px 8px 4px;
    border-bottom: 1px solid var(--border);
    margin-top: 4px;
}
.inv-recommended {
    background: rgba(0,230,118,0.04);
    border-color: rgba(0,230,118,0.15) !important;
}
.inv-recommended:hover {
    background: rgba(0,230,118,0.08) !important;
}

/* ── Morning Briefing ────────────────────────────────────────────── */
#briefing-card {
    margin: 8px 12px 0;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 6px;

    overflow: hidden;
    animation: briefSlide 0.3s ease-out;
}
@keyframes briefSlide {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}
.briefing-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
}
.briefing-day {
    font-family: 'Space Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--accent);
}
.briefing-date {
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    color: var(--fg2);
}
.briefing-hint {
    padding: 8px 14px;
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    color: var(--fg);
    background: rgba(0, 212, 255, 0.04);
    border-bottom: 1px solid var(--border);
}
.briefing-grid {
    display: flex;
    gap: 1px;
    background: var(--border);
}
.briefing-cell {
    flex: 1;
    padding: 10px 14px;
    background: var(--surface);
    min-width: 0;
}
.briefing-cell-label {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    text-transform: uppercase;
    color: var(--fg2);

    letter-spacing: 0.5px;
    margin-bottom: 4px;
}
.briefing-cell-value {
    font-family: 'Rajdhani', sans-serif;
    font-size: 22px;
    font-weight: 600;
    line-height: 1;
}
.briefing-cell-detail {
    font-family: 'DM Sans', sans-serif;
    font-size: 10px;
    color: var(--fg2);
    margin-top: 4px;
}
.briefing-cell-value.shortage { color: var(--red); }
.briefing-cell-value.tight { color: var(--yellow); }
.briefing-cell-value.ok { color: var(--green); }
.briefing-cell-value.info { color: var(--accent); }

/* ── Settings View ───────────────────────────────────────────────── */
.settings-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    padding: 12px;
}
.settings-panel .panel-body {
    padding: 10px 14px;
}
.settings-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}
.settings-row label {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--fg2);
    text-transform: uppercase;
    min-width: 180px;
    flex-shrink: 0;
}
.settings-input {
    flex: 1;
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 4px;
    color: var(--fg);

    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    padding: 5px 8px;
    outline: none;
}
.settings-input:focus {
    border-color: var(--accent);
}
/* ── Waste / Audit / Lead Time ───────────────────────────────────── */
.waste-form {
    display: flex;
    gap: 8px;
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
    align-items: flex-end;
}
.waste-form label {
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    color: var(--fg2);
    text-transform: uppercase;
    display: block;
    margin-bottom: 3px;
}
.waste-form input, .waste-form select {
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 4px;
    color: var(--fg);
    font-family: 'DM Sans', sans-serif;
    font-size: 11px;
    padding: 4px 6px;
}
.audit-action {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--accent);
    text-transform: uppercase;
}
.sparkline {
    display: inline-block;
    vertical-align: middle;
    margin-left: 4px;
}

/* ── Cut Order View ─────────────────────────────────────────────── */
#cutorder-view {
    padding: 8px 16px;
}
#cutorder-header {

    margin-bottom: 8px;
}
#co-lines-panel {
    margin-bottom: 8px;
}
#co-lines-panel .net-table-wrap {
    max-height: calc(100vh - 320px);
}
.cut-row-shortage td { border-left: 3px solid var(--red) !important; }
.cut-row-shortage .co-net { color: var(--red); font-weight: 700; }
.cut-row-mfg td { border-left: 3px solid var(--orange) !important; }
.cut-row-mfg .co-net { color: var(--orange); font-weight: 600; }
.cut-row-ok td { border-left: 3px solid transparent; }
.cut-row-ok .co-net { color: var(--green); }
.cut-row-surplus td { border-left: 3px solid var(--green) !important; }
.cut-row-surplus .co-net { color: var(--green); font-weight: 500; }
.cut-row-nodemand td { opacity: 0.4; }

#co-table .co-sku {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    cursor: pointer;
}
#co-table .co-sku:hover {
    color: var(--accent);
    text-decoration: underline;
}
#co-table .co-cut {
    font-family: 'Rajdhani', sans-serif;
    font-weight: 600;
    color: var(--orange);
}
#co-shortages-panel, #co-surplus-panel {
    margin-bottom: 8px;
}
#co-projection-panel {
    margin-bottom: 8px;
}

/* Attribution drawer detail */
.attr-section {
    margin-bottom: 12px;
}
.attr-section-title {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--fg2);
    margin-bottom: 4px;

}
.attr-row {
    display: flex;
    justify-content: space-between;
    padding: 2px 8px;
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
}
.attr-row .attr-label { color: var(--fg); }
.attr-row .attr-value {
    font-family: 'Rajdhani', sans-serif;
    font-weight: 600;
    color: var(--accent);
}
.attr-prcjam { color: var(--accent) !important; }
.attr-cexec { color: #b894f0 !important; }
.attr-direct { color: var(--fg) !important; }

/* Monthly Boxes */
.monthly-box-panel { margin-bottom: 12px; }
.mb-header { display: flex; align-items: center; gap: 10px; padding: 6px 0; border-bottom: 1px solid var(--sep, #2a2a2d); }
.mb-type { font-family: 'Space Mono', monospace; font-weight: 600; font-size: 12px; color: var(--accent, #00d4ff); }
.mb-count-input { width: 50px; background: var(--bg2, #131316); border: 1px solid var(--sep, #2a2a2d); color: var(--fg, #e0e0e0); font-family: 'Rajdhani', sans-serif; font-size: 13px; padding: 2px 6px; border-radius: 3px; }
.mb-count-label { font-family: 'Rajdhani', sans-serif; font-size: 13px; font-weight: 500; color: var(--accent, #00d4ff); }
.mb-table { width: 100%; }
.mb-slot-name { font-size: 11px; color: var(--fg2, #888); white-space: nowrap; }
.mb-sku-cell { cursor: pointer; font-family: 'DM Sans', sans-serif; font-size: 12px; }
.mb-sku-cell.assigned { color: var(--green, #00e676); }
.mb-sku-cell.unassigned { color: var(--fg2, #888); }
.mb-sku-cell:hover { background: rgba(0,212,255,0.1); }

/* ══ Runway View ══════════════════════════════════════════════════════ */

#runway-view { padding: 0 12px 12px; }
#runway-header { margin-bottom: 8px; }
.rw-legend {
    display: flex; gap: 16px; padding: 6px 12px; align-items: center;
    font-family: 'Space Mono', monospace; font-size: 11px;
    color: var(--fg2); text-transform: uppercase; letter-spacing: 1px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 8px;
}
.rw-legend-item { display: flex; align-items: center; gap: 5px; }
.rw-legend-swatch {
    display: inline-block; width: 20px; height: 10px;
    border-radius: 2px;
}
.rw-swatch-solid { background: var(--rw-bar-ok); opacity: 0.7; }
.rw-swatch-striped {
    background: repeating-linear-gradient(

        -45deg, var(--rw-bar-ok), var(--rw-bar-ok) 2px,
        transparent 2px, transparent 4px
    );
    opacity: 0.6;
}
.rw-swatch-ghost {
    background: transparent;
    border: 1px dashed rgba(255,255,255,0.4);
}
.rw-legend-dot {
    display: inline-block; width: 8px; height: 8px;
    border-radius: 50%;
}
.rw-legend-sep { flex: 1; }
.rw-toggle-hidden {
    font-family: 'Space Mono', monospace; font-size: 11px;
    color: var(--fg3); cursor: pointer; padding: 2px 8px;
    border: 1px solid var(--border); border-radius: 3px;
    background: transparent; text-transform: uppercase; letter-spacing: 1px;
}
.rw-toggle-hidden:hover { color: var(--fg); border-color: var(--fg3); }
.rw-toggle-hidden.active { color: var(--warm); border-color: var(--warm); }
.rw-body {
    display: flex; gap: 12px; height: calc(100vh - 180px);
}
.rw-assignments {
    width: 280px; min-width: 240px; flex-shrink: 0;
    background: var(--surface); border: 1px solid var(--border);
    border-radius: var(--radius); padding: 8px;
    overflow-y: auto;
}
.rw-grid {
    flex: 1; overflow-y: auto; overflow-x: hidden;
    background: var(--surface); border: 1px solid var(--border);
    border-radius: var(--radius); padding: 0 6px;
}

/* Assignment panel */
.rw-assign-title {
    font-family: 'Space Mono', monospace; font-size: 10px;
    text-transform: uppercase; letter-spacing: 1.5px;
    color: var(--fg2); margin-bottom: 8px; padding-bottom: 4px;
    border-bottom: 1px solid var(--border);
}
.rw-assign-table { width: 100%; border-collapse: collapse; }
.rw-assign-table th {
    font-family: 'Space Mono', monospace; font-size: 9px;
    text-transform: uppercase; letter-spacing: 1px; color: var(--fg3);
    text-align: left; padding: 4px 6px;
    border-bottom: 1px solid var(--border);

}
.rw-assign-table td {
    padding: 5px 6px; font-family: 'DM Sans', sans-serif; font-size: 12px;
    border-bottom: 1px solid rgba(42,42,48,0.5);
}
.rw-assign-table tr:hover { background: rgba(0,212,255,0.04); }
.rw-cur-label {
    font-family: 'Space Mono', monospace; font-weight: 600;
    font-size: 11px; color: var(--accent);
}
.rw-cheese-cell {
    cursor: pointer; color: var(--fg);
    transition: color 0.2s;
}
.rw-cheese-cell:hover { color: var(--accent); }
.rw-cheese-cell.unassigned { color: var(--fg3); font-style: italic; }
.rw-spark-wrap { display: flex; align-items: center; gap: 4px; }
.rw-sparkline {
    display: inline-block; height: 4px;
    background: var(--accent); border-radius: 2px;
    max-width: 60px; min-width: 2px;
    opacity: 0.7;
}
.rw-sparkline.cexec { background: #b894f0; }
.rw-spark-units {
    font-family: 'Rajdhani', sans-serif; font-size: 9px;
    font-weight: 500; color: var(--fg2);
}

/* Runway grid — continuous bar layout */
.rw-grid-table { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; }
.rw-grid-table thead { position: sticky; top: 0; z-index: 2; }
.rw-grid-table th {
    font-family: 'Space Mono', monospace; font-size: 10px;
    font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;
    color: var(--fg2); text-align: left; padding: 4px 3px;
    border-bottom: 1px solid var(--border);
    background: var(--surface);
}
.rw-grid-table th.rw-th-runway { text-align: center; }
.rw-grid-table th.rw-th-weeks { text-align: right; width: 50px; }
.rw-grid-table td {
    padding: 3px; border-bottom: 1px solid rgba(42,42,48,0.3);
    vertical-align: middle;
}
.rw-sku-col {
    font-family: 'DM Sans', sans-serif; font-size: 12px;
    color: var(--fg); white-space: nowrap;
    overflow: hidden; text-overflow: ellipsis;
}

.rw-sku-name {
    font-size: 9px; color: var(--fg3); display: block;
    overflow: hidden; text-overflow: ellipsis;
}
.rw-avail-col {
    font-family: 'Rajdhani', sans-serif; font-size: 14px;
    font-weight: 500; color: var(--fg2); text-align: right;
    white-space: nowrap; padding: 3px 6px !important;
    border-left: 1px solid rgba(255,255,255,0.06);
    border-right: 1px solid rgba(255,255,255,0.06);
}
.rw-hide-btn {
    display: inline-block; width: 18px; height: 18px; line-height: 18px;
    text-align: center; font-size: 13px; color: var(--fg3);
    cursor: pointer; border-radius: 2px; opacity: 0;
    transition: opacity 0.15s;
}
tr:hover .rw-hide-btn { opacity: 1; }
.rw-hide-btn:hover { color: var(--red); background: rgba(255,59,92,0.15); }

/* Continuous bar cell */
.rw-bar-cell {
    position: relative; height: 20px;
}
.rw-bar-track {
    position: absolute; top: 2px; left: 0; right: 0; bottom: 2px;
    background: rgba(255,255,255,0.03); border-radius: 3px;
    overflow: hidden;
}
.rw-fill-processed {
    position: absolute; top: 0; bottom: 0; left: 0;
    border-radius: 3px 0 0 3px;
    transition: width 0.5s ease;
}
.rw-fill-potential {
    position: absolute; top: 0; bottom: 0;
    border-radius: 0 3px 3px 0;
    opacity: 0.55; transition: width 0.5s ease, left 0.5s ease;
}
.rw-ghost {
    position: absolute; top: 0; bottom: 0;
    border-right: 2px dashed rgba(255,255,255,0.25);
    pointer-events: none; transition: left 0.5s ease;
    z-index: 1;
}
/* Week tick marks on the continuous bar */
.rw-week-tick {
    position: absolute; top: 0; bottom: 0; width: 1px;
    background: rgba(255,255,255,0.35);
    pointer-events: none;

}
.rw-week-label-overlay {
    position: absolute; top: 50%; font-family: 'Rajdhani', sans-serif;
    font-size: 10px; font-weight: 600; color: rgba(255,255,255,0.55);
    pointer-events: none; transform: translate(3px, -50%);
    letter-spacing: 0.3px; white-space: nowrap;
}

/* Warmer status colors for runway */
.rw-fill-processed.rw-ok { background: var(--rw-bar-ok); opacity: 0.75; }
.rw-fill-processed.rw-tight { background: var(--rw-bar-tight); opacity: 0.75; }
.rw-fill-processed.rw-shortage { background: var(--rw-bar-shortage); opacity: 0.75; }

.rw-fill-potential.rw-ok {
    background: repeating-linear-gradient(-45deg, var(--rw-bar-ok), var(--rw-bar-ok) 3px, transparent 3px, transparent 6px);
}
.rw-fill-potential.rw-tight {
    background: repeating-linear-gradient(-45deg, var(--rw-bar-tight), var(--rw-bar-tight) 3px, transparent 3px, transparent 6px);
}
.rw-fill-potential.rw-shortage {
    background: repeating-linear-gradient(-45deg, var(--rw-bar-shortage), var(--rw-bar-shortage) 3px, transparent 3px, transparent 6px);
}

/* Runway weeks column — warm tones */
.rw-runway-col {
    font-family: 'Rajdhani', sans-serif; font-size: 14px;
    font-weight: 600; text-align: right; white-space: nowrap;
}
.rw-runway-col.rw-ok { color: var(--rw-bar-ok); }
.rw-runway-col.rw-tight { color: var(--rw-bar-tight); }
.rw-runway-col.rw-shortage { color: var(--rw-bar-shortage); }

/* Runway row shortage/tight accent — left border on the row via :has() */
.rw-grid-table tbody tr:has(.rw-runway-col.rw-shortage) td:nth-child(2) {
    border-left: 3px solid var(--rw-bar-shortage);
    padding-left: 6px;
}
.rw-grid-table tbody tr:has(.rw-runway-col.rw-tight) td:nth-child(2) {
    border-left: 3px solid var(--rw-bar-tight);
    padding-left: 6px;
}

/* Demand/wk column */
.rw-demand-col {
    font-family: 'Rajdhani', sans-serif; font-size: 14px;
    font-weight: 500; color: var(--fg2); text-align: left;
    white-space: nowrap; cursor: pointer;
    padding: 3px 6px !important; transition: background 0.15s;
    border-left: 1px solid rgba(255,255,255,0.06);
    border-right: 1px solid rgba(255,255,255,0.06);

}
.rw-demand-col:hover { background: rgba(255,255,255,0.04); }
.rw-demand-num { margin-right: 2px; }
.rw-expand-icon {
    font-size: 8px; color: var(--fg3); opacity: 0.5;
    transition: transform 0.2s, opacity 0.15s;
    display: inline-block;
}
.rw-demand-col:hover .rw-expand-icon { opacity: 1; }
.rw-pot-hint {
    font-size: 10px; color: var(--fg3); opacity: 0.7;
}
.rw-th-num {
    text-align: right; padding-right: 4px !important;
}
.rw-th-num.rw-th-dmd {
    text-align: left; padding-left: 4px !important; padding-right: 0 !important;
}

/* Demand breakdown expandable row */
.rw-breakdown-row td {
    padding: 0 4px 4px 4px !important;
    border-bottom: 1px solid rgba(42,42,48,0.15) !important;
}
.rw-breakdown-cell {
    font-family: 'Space Mono', monospace; font-size: 10px;
    color: var(--fg3); padding-left: 130px !important;
}
.rw-bd-item { white-space: nowrap; }
.rw-bd-item b { color: var(--fg2); font-weight: 600; }
.rw-bd-sep {
    margin: 0 8px; color: var(--fg3); opacity: 0.4;
}

/* Inline action chips on shortage rows */
.rw-chip {
    display: inline-block; font-family: 'Space Mono', monospace;
    font-size: 8px; padding: 1px 5px; border-radius: 3px;
    margin-left: 4px; white-space: nowrap; cursor: default;
    max-width: 120px; overflow: hidden; text-overflow: ellipsis;
    vertical-align: middle;
}
/* Horizon toggle button */
.rw-horizon-toggle {
    display: inline-flex; background: var(--bg2); border: 1px solid var(--border);
    border-radius: 4px; padding: 0; overflow: hidden; cursor: pointer;
    margin-right: 8px;
}
.rw-hz-opt {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 600;

    padding: 4px 10px; color: var(--fg3); transition: all 0.15s;
    letter-spacing: 0.5px;
}
.rw-hz-opt.rw-hz-active {
    background: var(--accent); color: var(--bg); border-radius: 3px;
}

.rw-chip-mfg { background: rgba(0,230,118,0.15); color: var(--green); }
.rw-chip-po { background: rgba(96,165,250,0.15); color: var(--blue); }
.rw-chip-other { background: rgba(255,136,0,0.12); color: var(--orange); }

/* ══ Activity Log Timeline ══════════════════════════════════════════ */
.tl-date-group {
    font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 600;
    color: var(--fg2); padding: 12px 0 4px; margin-top: 4px;
    border-bottom: 1px solid var(--border); letter-spacing: 0.5px;
}
.tl-entry {
    display: flex; align-items: flex-start; gap: 8px;
    padding: 6px 4px; border-bottom: 1px solid rgba(42,42,48,0.2);
}
.tl-entry:hover { background: rgba(255,255,255,0.02); }
.tl-icon {
    font-size: 10px; width: 16px; text-align: center;
    flex-shrink: 0; margin-top: 2px;
}
.tl-icon.tl-in { color: var(--green); }
.tl-icon.tl-out { color: var(--red); }
.tl-icon.tl-status { color: var(--blue); }
.tl-content { flex: 1; min-width: 0; }
.tl-header {
    display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
}
.tl-type {
    font-family: 'Space Mono', monospace; font-size: 9px;
    text-transform: uppercase; letter-spacing: 0.5px;
    color: var(--fg3); min-width: 80px;
}
.tl-summary {
    font-family: 'DM Sans', sans-serif; font-size: 12px;
    color: var(--fg); flex: 1;
}
.tl-units {
    font-family: 'Rajdhani', sans-serif; font-size: 13px; font-weight: 600;
    white-space: nowrap;
}
.tl-units.tl-in { color: var(--green); }
.tl-units.tl-out { color: var(--red); }
.tl-expand {
    font-family: 'Space Mono', monospace; font-size: 9px;

    color: var(--fg3); cursor: pointer; white-space: nowrap;
}
.tl-expand:hover { color: var(--fg); }
.tl-detail {
    padding: 4px 0 4px 24px;
    display: flex; flex-wrap: wrap; gap: 4px 12px;
}
.tl-sku-item {
    font-family: 'DM Sans', sans-serif; font-size: 11px;
    color: var(--fg2); white-space: nowrap;
}
.tl-sku-item .tl-in { color: var(--green); font-weight: 600; }
.tl-sku-item .tl-out { color: var(--red); font-weight: 600; }

/* ── Cut Order Calculator ──────────────────────────────────────────── */
#cutorder-view { display: flex; flex-direction: column; }
/* Side-by-side layout: table + assignment panel */
.co-body-flex { display: flex; gap: 12px; }
.co-body-flex #co-lines-panel { flex: 1; min-width: 0; }
.co-body-flex #co-assign-drawer { flex-shrink: 0; }

/* Table — auto layout, stretches to fill */
.co-calc-table { border-spacing: 0; border-collapse: collapse; table-layout: auto; width: auto; min-width: 100%; }
.co-calc-table th {
    white-space: nowrap; padding: 6px 14px;
    font-family: 'Space Mono', monospace; font-size: 10px;
    letter-spacing: -0.5px;
}
.co-calc-table td { padding: 4px 14px; }
/* Week separators — collapsed, spacing via adjacent column padding */
.co-calc-table .co-wk-sep {
    display: none;
}
/* Extra left padding at group boundaries */
.co-calc-table th:nth-child(3),
.co-calc-table td:nth-child(3),
.co-calc-table th:nth-child(6),
.co-calc-table td:nth-child(6),
.co-calc-table th:nth-child(11),
.co-calc-table td:nth-child(11) {
    padding-left: 110px !important;
}
.co-calc-table .co-input-hdr { color: var(--accent); }
/* Category headers */
.co-calc-table .co-cat-row td {
    font-family: 'Space Mono', monospace; font-size: 14px; font-weight: 700;
    color: var(--green); text-transform: uppercase; padding: 12px 5px 4px;
    border-bottom: 1px solid var(--border); letter-spacing: 1px;
    border-left: 4px solid var(--green);
}

/* SKU cell */
.co-sku-cell {
    font-family: 'Space Mono', monospace; font-size: 11px;
    cursor: pointer; white-space: nowrap;
}
.co-sku-cell:hover { color: var(--accent); text-decoration: underline; }
/* Name cell — tab-sized gap after name before Avail */
.co-name-cell {
    font-family: 'DM Sans', sans-serif; font-size: 11px;
    color: var(--fg2); white-space: nowrap;
    padding-right: 12px !important;
}
/* Avail / Supply cells — distinct font */
.co-num {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 600;
    white-space: nowrap; text-align: right;
}
/* Week data numeric cells (Dmd, After, Status) */
.co-calc-table .num {
    padding: 2px 14px; white-space: nowrap; text-align: right;
    font-family: 'Rajdhani', sans-serif; font-size: 13px; font-weight: 500;
}
/* Cut input — fits 4+ chars */
.co-cut-input {
    width: 60px; text-align: right; padding: 3px 6px;
    font-family: 'Rajdhani', sans-serif; font-size: 13px; font-weight: 600;
    color: #4488ff; background: rgba(68,136,255,0.08);
    border: 1px solid rgba(68,136,255,0.25); border-radius: 3px;
}
.co-cut-input:focus {
    outline: none; border-color: var(--accent);
    background: rgba(68,136,255,0.15);
    box-shadow: 0 0 6px rgba(68,136,255,0.3);
}
/* Status badges */
.co-good-ok {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 700;
    color: var(--green);
}
.co-good-need {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 700;
    color: var(--red);
}
td[data-field="goodW2"] { padding-left: 20px; }
.co-status-hdr { padding-left: 20px; }
.co-after-ok { color: var(--green); }
.co-after-short { color: var(--red); font-weight: 700; }
.co-supply-badge {
    font-size: 12px; color: var(--accent); opacity: 0.8;
    font-family: 'Rajdhani', sans-serif; font-weight: 600;

}
/* Row-level color affordances */
.co-row-need { background: rgba(var(--red-rgb), 0.05); }
.co-row-ok { background: rgba(var(--green-rgb), 0.03); }
.co-filter-toggle {
    font-family: 'Space Mono', monospace; font-size: 10px;
    color: var(--fg2); cursor: pointer; display: flex; align-items: center; gap: 4px;
}
/* Table scroll container */
.co-table-wrap {
    overflow-x: auto; overflow-y: auto;
}

/* ── Assignment Panel (always visible, right side) ──────────────── */
#co-assign-drawer {
    width: 300px; min-width: 280px;
    border: 1px solid var(--border); border-radius: 6px;
    background: var(--surface); padding: 10px 12px;
    align-self: flex-start;
}
.co-assign-header {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 600;
    text-transform: uppercase; letter-spacing: 1px; color: var(--accent);
    padding-bottom: 8px; margin-bottom: 6px;
    border-bottom: 1px solid var(--border);
}
.co-assign-section { margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px solid var(--border); }
.co-assign-section:last-child { border-bottom: none; padding-bottom: 0; }
.co-assign-title {
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 700;
    text-transform: uppercase; color: var(--accent); letter-spacing: 1px;
    margin-bottom: 6px; padding-bottom: 4px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}
.co-assign-row {
    display: flex; align-items: center; gap: 6px;
    padding: 3px 0;
}
.co-assign-suffix {
    font-family: 'DM Sans', sans-serif; font-size: 13px; font-weight: 500;
    color: var(--fg); min-width: 55px;
}
.co-assign-demand {
    font-family: 'Rajdhani', sans-serif; font-size: 15px; font-weight: 600;
    color: var(--warm); min-width: 35px; text-align: right;
}
.co-assign-input {
    flex: 1; min-width: 0;
    font-family: 'Space Mono', monospace; font-size: 12px;
    color: var(--fg); background: var(--bg2);

    border: 1px solid var(--border); border-radius: 3px;
    padding: 3px 6px;
}
.co-assign-input:focus {
    outline: none; border-color: var(--accent);
    background: rgba(0,212,255,0.05);
}
.co-assign-hdr-row {
    display: flex; align-items: center; gap: 6px;
    padding: 2px 0 4px; font-family: 'Space Mono', monospace;
    font-size: 9px; text-transform: uppercase; color: var(--fg3);
    letter-spacing: 0.5px;
}
.co-assign-hdr-row span:first-child { min-width: 55px; }
.co-assign-hdr-row span:nth-child(2),
.co-assign-hdr-row span:nth-child(3) { min-width: 35px; text-align: right; }
.co-assign-hdr-row span:nth-child(4) { flex: 1; }
.co-assign-w2 { color: var(--fg3); }

/* ── Projection Settings Grid ──────────────────────────────────── */
.co-proj-grid {
    display: grid; grid-template-columns: auto auto auto auto auto;
    gap: 8px 16px; align-items: center;
}
.co-proj-group { display: flex; align-items: center; gap: 6px; }
.co-proj-label {
    font-family: 'Space Mono', monospace; font-size: 10px;
    text-transform: uppercase; color: var(--fg2);
    white-space: nowrap; display: flex; align-items: center; gap: 4px;
}

/* ── Morning Briefing Banner ─────────────────────────────────────── */
.briefing-banner {
    margin: 8px 12px; padding: 10px 14px; border-radius: 6px;
    font-family: 'DM Sans', sans-serif; font-size: 12px;
    border-left: 4px solid var(--accent);
    background: rgba(0, 212, 255, 0.06);
}
.briefing-critical { border-left-color: #ff3b5c; background: rgba(255, 59, 92, 0.08); }
.briefing-warn { border-left-color: #ff8800; background: rgba(255, 136, 0, 0.06); }
.briefing-ok { border-left-color: var(--green); background: rgba(0, 230, 118, 0.06); }
.briefing-header {
    display: flex; align-items: center; gap: 12px; margin-bottom: 6px;
}
.briefing-day {
    font-family: 'Space Mono', monospace; font-size: 13px; font-weight: 600;
    color: var(--accent);
}
.briefing-ship { font-size: 11px; color: #aaa; }
.briefing-badge {

    font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 600;
    background: #ff8800; color: #000; padding: 2px 6px; border-radius: 3px;
    text-transform: uppercase;
}
.briefing-actions { display: flex; flex-direction: column; gap: 3px; }
.briefing-action {
    font-size: 11px; color: #ccc; padding-left: 8px;
    border-left: 2px solid rgba(255,255,255,0.1);
}
.briefing-meta {
    font-size: 10px; color: #666; margin-top: 6px;
    font-family: 'Space Mono', monospace;
}

/* ── Smart PO ────────────────────────────────────────────────────── */
.smart-po-vendor { margin-bottom: 12px; }
.smart-po-vendor-header {
    display: flex; align-items: center; gap: 12px; padding: 6px 8px;
    background: var(--bg2); border-radius: 4px 4px 0 0;
    font-family: 'Space Mono', monospace; font-size: 12px; font-weight: 600;
    color: var(--accent);
}
.smart-po-vendor-header span:nth-child(2) {
    font-size: 10px; font-weight: 400; color: #888;
}

/* ═══════════════════════════════════════════════════════════════════
   Curation Manager
   ═══════════════════════════════════════════════════════════════════ */

/* Card grid */
.cur-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 12px;
    padding-bottom: 40px;
    max-height: calc(100vh - 130px);
    overflow-y: auto;
}

.cur-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 14px;
    cursor: pointer;
    transition: border-color 0.15s, box-shadow 0.15s;
    position: relative;
}
.cur-card:hover {

    border-color: var(--accent2);
    box-shadow: 0 0 12px rgba(0,212,255,0.08);
}
.cur-card.inactive {
    opacity: 0.5;
}

.cur-card-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
}
.cur-card-key {
    font-family: 'Space Mono', monospace;
    font-size: 14px;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 1px;
}
.cur-card-label {
    font-size: 12px;
    color: var(--fg2);
}
.cur-card-type {
    margin-left: auto;
    font-family: 'Space Mono', monospace;
    font-size: 9px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: 2px 6px;
    border-radius: 3px;
    background: rgba(0,212,255,0.1);
    color: var(--accent);
}
.cur-card-type.monthly {
    background: rgba(255,136,0,0.1);
    color: var(--orange);
}

.cur-card-recipe {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-bottom: 8px;
}
.cur-sku-chip {
    font-family: 'Rajdhani', sans-serif;
    font-size: 11px;

    font-weight: 500;
    padding: 2px 6px;
    border-radius: 3px;
    background: var(--bg2);
    color: var(--fg);
    border: 1px solid var(--border);
    white-space: nowrap;
}
.cur-sku-chip.cheese { border-left: 2px solid var(--cheese); }
.cur-sku-chip.meat { border-left: 2px solid var(--red); }
.cur-sku-chip.acc { border-left: 2px solid var(--green); }

.cur-card-assignments {
    display: flex;
    gap: 8px;
    font-family: 'Rajdhani', sans-serif;
    font-size: 11px;
    color: var(--fg2);
}
.cur-card-assign {
    display: flex;
    align-items: center;
    gap: 3px;
}
.cur-card-assign .dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    display: inline-block;
}
.cur-card-assign .dot.pr { background: var(--blue); }
.cur-card-assign .dot.ec { background: var(--orange); }

.cur-card-dates {
    font-family: 'Rajdhani', sans-serif;
    font-size: 11px;
    color: var(--orange);
    margin-top: 6px;
}

/* Filter buttons */
.cur-filter.active {
    background: var(--accent) !important;
    color: var(--bg) !important;
}

/* Editor overlay */
.cur-overlay {
    position: fixed;
    inset: 0;
    z-index: 1000;

    display: flex;
    align-items: center;
    justify-content: center;
}
.cur-editor-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.6);
}
.cur-editor-panel {
    position: relative;
    z-index: 1;
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 16px;
    width: 90vw;
    max-width: 960px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: var(--shadow-lg);
}
.cur-editor-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
    flex-wrap: wrap;
}

.cur-key-input {
    font-family: 'Space Mono', monospace;
    font-size: 14px;
    font-weight: 700;
    color: var(--accent);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 6px 10px;
    width: 160px;
    letter-spacing: 1px;
}
.cur-label-input {
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    color: var(--fg);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 6px 10px;

    width: 200px;
}
.cur-active-toggle {
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    color: var(--fg2);
    display: flex;
    align-items: center;
    gap: 4px;
    cursor: pointer;
}

/* Recipe list in editor */
#cur-recipe-list .cur-recipe-row {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px;
    border-bottom: 1px solid var(--border);
    font-size: 12px;
}
#cur-recipe-list .cur-recipe-row:hover {
    background: var(--surface2);
}
#cur-recipe-list .cur-recipe-sku {
    font-family: 'Rajdhani', sans-serif;
    font-weight: 500;
    color: var(--fg);
    flex: 1;
}
#cur-recipe-list .cur-recipe-name {
    font-size: 11px;
    color: var(--fg2);
    flex: 2;
}
#cur-recipe-list .cur-recipe-qty {
    width: 40px;
    text-align: center;
    font-family: 'Rajdhani', sans-serif;
    font-weight: 600;
    color: var(--accent);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 3px;
    padding: 2px;
}
#cur-recipe-list .cur-recipe-remove {
    color: var(--red);
    cursor: pointer;
    font-size: 14px;

    opacity: 0.6;
    transition: opacity 0.15s;
}
#cur-recipe-list .cur-recipe-remove:hover { opacity: 1; }

/* Assignment groups */
.cur-assign-group {
    margin-bottom: 12px;
}
.cur-assign-label {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    color: var(--fg2);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 4px;
    display: block;
}

/* Checkbox styling */
.cur-checkbox {
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    color: var(--fg);
    display: flex;
    align-items: center;
    gap: 4px;
    cursor: pointer;
}

/* Addon bundle list */
.addon-row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    border-bottom: 1px solid var(--border);
    font-size: 12px;
}
.addon-row:hover { background: var(--surface2); }
.addon-key {
    font-family: 'Space Mono', monospace;
    font-size: 12px;
    font-weight: 600;
    color: var(--orange);
    width: 150px;
}
.addon-name {
    flex: 1;

    color: var(--fg);
}
.addon-children {
    font-family: 'Rajdhani', sans-serif;
    font-size: 11px;
    color: var(--fg2);
}

/* Demand preview table */
.demand-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}
.demand-table th {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 6px 8px;
    text-align: left;
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    background: var(--bg2);
}
.demand-table td {
    padding: 5px 8px;
    border-bottom: 1px solid var(--border);
    font-family: 'Rajdhani', sans-serif;
    font-weight: 500;
}
.demand-table tr:hover td { background: var(--surface2); }

/* CEX-EC split row */
.cur-split-row {
    display: flex;
    gap: 4px;
    align-items: center;
    margin-bottom: 4px;
}
.cur-split-row select { flex: 1; }
.cur-split-row input[type="number"] {
    width: 50px;
    text-align: center;
    font-family: 'Rajdhani', sans-serif;
    background: var(--surface);
    border: 1px solid var(--border);

    border-radius: 3px;
    color: var(--fg);
    padding: 2px 4px;
}

/* Addon checkbox in editor */
.cur-addon-check {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 0;
    font-size: 12px;
    color: var(--fg);
    border-bottom: 1px solid var(--border);
}
.cur-addon-check label {
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cur-addon-check .addon-detail {
    font-family: 'Rajdhani', sans-serif;
    font-size: 11px;
    color: var(--fg2);
}

/* Command Center — Ground Control Theme */
/* Design: Deep space ops center. No red. No AI slop. */

/* ── Layout fix: force two-column grid ─────────────────────────────
   styles.css line 183 sets #app to display:grid with rows but no
   column spec, so sidebar (height:100vh) consumes the whole first
   row and main-area collapses to 0 height at y=viewport-bottom.
   Content renders off-screen. Override to a proper sidebar+main grid. */
#app {
    display: grid !important;
    grid-template-columns: 180px 1fr !important;
    grid-template-rows: 1fr !important;
    height: 100vh;
}
#sidebar { grid-column: 1; grid-row: 1; }
#main-area { grid-column: 2; grid-row: 1; min-height: 0; display: flex; flex-direction: column; }
/* Overlays + floating elements stay in auto-placement; pin them out of the grid flow */
#mascot, #drag-ghost, #subs-overlay, #picker-overlay, #mascot-speech,
#cur-editor-overlay, #addon-overlay, #demand-preview-overlay {
    grid-column: 1 / -1;
    grid-row: 1;
    pointer-events: auto;
}
/* main-area children need to fill its height */
#main-area > #commandcenter-view,
#main-area > #content,
#main-area > #runway-view,
#main-area > #calendar-view,
#main-area > #invoices-view,
#main-area > #cutorder-view,
#main-area > #log-view,
#main-area > #settings-view {
    flex: 1 1 auto;
    min-height: 0;
}

/* ── A11y: focus, reduced motion, high contrast ── */
.cc-task-card:focus-visible,
.cc-task-action-btn:focus-visible,
.cc-blocker-resolve-btn:focus-visible,
.cc-chat-input input:focus-visible,
.cc-chat-input button:focus-visible {
    outline: 2px solid #4ecca3;
    outline-offset: 2px;
}

.cc-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;

    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

@media (prefers-reduced-motion: reduce) {
    .cc-timer-display.cc-timer-overrun { animation: none; }
    .cc-timer-fill { transition: none; }
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

@media (prefers-contrast: more) {
    :root {
        --cc-border: rgba(255, 255, 255, 0.25);
    }
    .cc-task-card { border-width: 2px; }
    .cc-task-title { font-weight: 600; }
    .cc-task-meta { font-weight: 500; }
}

/* ── Tokens ── */
:root {
    --cc-base: #08090d;
    --cc-surface: #0f1118;
    --cc-elevated: #161a26;
    --cc-raised: #1c2030;
    --cc-border: rgba(255, 255, 255, 0.06);
    --cc-border-hover: rgba(255, 255, 255, 0.12);
    --cc-text-1: #e8eaf0;
    --cc-text-2: #9098a8;
    --cc-text-3: #5a6278;
    --cc-accent: #4ecca3;
    --cc-accent-dim: rgba(78, 204, 163, 0.12);
    --cc-accent-glow: rgba(78, 204, 163, 0.25);
    --cc-indigo: #818cf8;
    --cc-indigo-dim: rgba(129, 140, 248, 0.12);
    --cc-amber: #f5a623;
    --cc-amber-dim: rgba(245, 166, 35, 0.12);
    --cc-shadow-sm: 0 1px 2px rgba(0,0,0,0.3), 0 2px 6px rgba(0,0,0,0.15);
    --cc-shadow-md: 0 2px 4px rgba(0,0,0,0.3), 0 8px 16px rgba(0,0,0,0.2);
    --cc-radius: 10px;
    --cc-radius-sm: 6px;
}

/* ── FUI Grid Background ── */
#commandcenter-view::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image:
        linear-gradient(rgba(78,204,163,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(78,204,163,0.03) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
    z-index: 0;
}

/* ── Layout ── */
.cc-layout {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 20px;
    height: calc(100vh - 60px);
    padding: 20px 24px;
    overflow: hidden;
    background: var(--cc-base);
    position: relative;
    z-index: 1;
}

@media (max-width: 1100px) {
    .cc-layout {
        grid-template-columns: 1fr;
        grid-template-rows: 1fr auto;
    }
    .cc-sidebar {
        flex-direction: row;
        gap: 12px;
        overflow-x: auto;
        max-height: 180px;
    }
    .cc-sidebar > * { min-width: 240px; }
}

/* ── Main Panel ── */
.cc-main {
    overflow-y: auto;
    padding-right: 12px;
}

.cc-main::-webkit-scrollbar { width: 5px; }
.cc-main::-webkit-scrollbar-track { background: transparent; }
.cc-main::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.08);

    border-radius: 3px;
}
.cc-main::-webkit-scrollbar-thumb:hover {
    background: rgba(255,255,255,0.14);
}

/* ── Header ── */
.cc-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--cc-border);
    position: relative;
}

.cc-header::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--cc-accent), transparent);
    opacity: 0.4;
}

.cc-greeting {
    font-family: 'Rajdhani', sans-serif;
    font-size: 26px;
    font-weight: 600;
    color: var(--cc-text-1);
    letter-spacing: -0.5px;
}

.cc-energy {
    display: flex;
    align-items: center;
    gap: 6px;
}

.cc-energy-label {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--cc-text-3);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-right: 4px;
}

.cc-energy-btn {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    padding: 10px 14px;
    min-height: 36px;
    border: 1px solid var(--cc-border);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-text-2);
    cursor: pointer;
    transition: all 200ms cubic-bezier(0.25, 1, 0.5, 1);
}

.cc-energy-btn:hover {
    border-color: var(--cc-accent);
    color: var(--cc-text-1);
    background: var(--cc-accent-dim);
}

.cc-energy-btn.active {
    background: var(--cc-accent-dim);
    border-color: var(--cc-accent);
    color: var(--cc-accent);
    box-shadow: 0 0 12px var(--cc-accent-glow);
}

/* ── Morning Brief ── */
.cc-brief {
    background: var(--cc-elevated);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius);
    margin-bottom: 20px;
    box-shadow: var(--cc-shadow-sm);
    overflow: hidden;
}

.cc-brief-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 16px;
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--cc-indigo);
    text-transform: uppercase;
    letter-spacing: 2px;
    background: var(--cc-indigo-dim);
    border-bottom: 1px solid var(--cc-border);
}

.cc-brief-dismiss {
    background: none;
    border: none;
    color: var(--cc-text-3);
    font-size: 16px;
    cursor: pointer;
    padding: 8px 10px;
    min-width: 36px;
    min-height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--cc-radius-sm);
    transition: color 150ms, background 150ms;
}
.cc-brief-dismiss:hover {
    background: rgba(255,255,255,0.06);
}

.cc-brief-dismiss:hover { color: var(--cc-text-1); }

.cc-brief-body {
    padding: 14px 16px;
    font-family: 'DM Sans', sans-serif;
    font-size: 14px;
    color: var(--cc-text-2);
    line-height: 1.7;
}

.cc-brief-item {
    padding: 4px 0;
}

/* ── Sections ── */
.cc-section {
    margin-bottom: 28px;
    animation: cc-section-in 400ms cubic-bezier(0.25, 1, 0.5, 1) both;
}

@keyframes cc-section-in {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

#cc-frog {
    background: linear-gradient(135deg, rgba(245,166,35,0.06) 0%, transparent 60%);
    border-radius: var(--cc-radius);
    padding: 12px;
    margin: -12px;

    margin-bottom: 28px;
}

#cc-quickwins {
    background: linear-gradient(135deg, rgba(78,204,163,0.06) 0%, transparent 60%);
    border-radius: var(--cc-radius);
    padding: 12px;
    margin: -12px;
    margin-bottom: 28px;
}

.cc-section-label {
    font-family: 'Space Mono', monospace;
    font-size: 12px;
    color: var(--cc-text-2);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 12px;
    padding-left: 2px;
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: default;
}

.cc-section-icon {
    font-size: 14px;
}

.cc-section-label::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--cc-border);
}

#cc-frog .cc-section-label { color: var(--cc-amber); }
#cc-frog .cc-section-label::after { background: var(--cc-amber-dim); }

#cc-quickwins .cc-section-label { color: var(--cc-accent); }
#cc-quickwins .cc-section-label::after { background: var(--cc-accent-dim); }

.cc-section-collapsed .cc-task-list { display: none; }

.cc-section-collapsed .cc-section-label {
    cursor: pointer;
    color: var(--cc-text-3);
    padding: 6px 2px;
    border-radius: var(--cc-radius-sm);
    transition: color 150ms, background 150ms;

}

.cc-section-collapsed .cc-section-label:hover {
    color: var(--cc-text-1);
    background: rgba(255,255,255,0.03);
}

.cc-section-collapsed .cc-section-label::before {
    content: '▸';
    margin-right: 8px;
    font-size: 10px;
    transition: transform 200ms cubic-bezier(0.25, 1, 0.5, 1);
}

.cc-section:not(.cc-section-collapsed) .cc-section-label[onclick]::before {
    content: '▾';
    margin-right: 8px;
    font-size: 10px;
}

.cc-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: 'Rajdhani', sans-serif;
    font-size: 12px;
    font-weight: 600;
    background: var(--cc-raised);
    color: var(--cc-text-2);
    padding: 1px 8px;
    border-radius: 10px;
    min-width: 22px;
}

/* ── Task Cards ── */
.cc-section-icon {
    font-style: normal;
    margin-right: 4px;
    font-size: 12px;
}

.cc-task-card {
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius);
    padding: 14px 16px;
    margin-bottom: 8px;
    cursor: pointer;
    transition: all 200ms cubic-bezier(0.25, 1, 0.5, 1);
    position: relative;

    box-shadow: var(--cc-shadow-sm);
    animation: cc-card-in 250ms cubic-bezier(0.25, 1, 0.5, 1) both;
}

@keyframes cc-card-in {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}

.cc-task-card:hover {
    border-color: var(--cc-border-hover);
    background: var(--cc-elevated);
    transform: translateY(-1px);
    box-shadow: var(--cc-shadow-md);
}

.cc-task-card.cc-task-frog {
    border-left: 4px solid var(--cc-amber);
    background: linear-gradient(135deg, var(--cc-amber-dim) 0%, var(--cc-surface) 50%);
    box-shadow: 0 0 20px rgba(245, 166, 35, 0.12), var(--cc-shadow-sm);
}

.cc-task-card.cc-task-frog:hover {
    background: linear-gradient(135deg, var(--cc-amber-dim) 0%, var(--cc-elevated) 50%);
    box-shadow: 0 0 28px rgba(245, 166, 35, 0.2), var(--cc-shadow-md);
}

.cc-task-card.cc-task-frog .cc-task-title {
    font-size: 16px;
    font-weight: 500;
}

.cc-task-card.cc-task-personal {
    border-left: 4px solid var(--cc-indigo);
    background: linear-gradient(135deg, var(--cc-indigo-dim) 0%, var(--cc-surface) 50%);
}

.cc-task-card.cc-task-blocked {
    opacity: 0.55;
    border-left: 3px solid var(--cc-amber);
}

.cc-task-card.cc-task-done {
    opacity: 0.4;
}

.cc-task-card.cc-task-done .cc-task-title {
    text-decoration: line-through;
}

.cc-task-title {
    font-family: 'DM Sans', sans-serif;
    font-size: 14px;
    font-weight: 500;
    color: var(--cc-text-1);
    margin-bottom: 6px;
    line-height: 1.4;
}

.cc-task-meta {
    display: flex;
    align-items: center;
    gap: 10px;
    font-family: 'Space Mono', monospace;
    font-size: 12px;
    color: var(--cc-text-2);
    margin-top: 4px;
}

.cc-task-priority {
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 2px 8px;
    border-radius: 3px;
    font-size: 11px;
}

.cc-task-priority.high { color: #fff; background: var(--cc-amber); }
.cc-task-priority.medium { color: var(--cc-text-1); background: var(--cc-elevated); }
.cc-task-priority.low { color: var(--cc-text-3); background: transparent; }

.cc-task-est { color: var(--cc-text-2); }

.cc-task-source {
    font-size: 11px;
    color: var(--cc-text-3);
}

.cc-task-actions {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 6px;
    opacity: 0;
    transition: opacity 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

.cc-task-card:hover .cc-task-actions { opacity: 1; }

.cc-task-action-btn {
    font-size: 10px;
    padding: 5px 12px;
    border: 1px solid var(--cc-border);
    border-radius: 20px;
    background: var(--cc-base);
    color: var(--cc-text-2);
    cursor: pointer;
    font-family: 'Space Mono', monospace;
    transition: all 0.15s;
    backdrop-filter: blur(8px);
}

.cc-task-action-btn:hover {
    background: var(--cc-raised);
    color: var(--cc-text-1);
}

.cc-task-action-btn.cc-start-btn {
    border-color: var(--cc-accent);
    color: var(--cc-accent);
}

.cc-task-action-btn.cc-start-btn:hover {
    background: var(--cc-accent-dim);
    box-shadow: 0 0 10px var(--cc-accent-glow);
}

/* ── Checklist ── */
.cc-checklist {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid var(--cc-border);
}

.cc-checklist-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 4px 0;
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    color: var(--cc-text-2);
    cursor: pointer;
    transition: color 0.15s;
}

.cc-checklist-item:hover { color: var(--cc-text-1); }

.cc-checklist-item.done {
    text-decoration: line-through;
    color: var(--cc-text-3);
}

.cc-checklist-check {
    width: 16px;
    height: 16px;
    border: 1.5px solid rgba(255,255,255,0.15);
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: all 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

.cc-checklist-item.done .cc-checklist-check {
    background: var(--cc-accent);
    border-color: var(--cc-accent);
    color: var(--cc-base);
    font-size: 11px;
    box-shadow: 0 0 8px var(--cc-accent-glow);
}

.cc-checklist-progress {
    margin-top: 8px;
    height: 3px;
    background: rgba(255,255,255,0.04);
    border-radius: 2px;
    overflow: hidden;
}

.cc-checklist-progress-fill {
    height: 100%;
    background: var(--cc-accent);
    border-radius: 2px;
    transition: width 0.3s cubic-bezier(0.25, 1, 0.5, 1);
}

/* ── Add Task Bar ── */
.cc-add-bar {
    display: flex;
    gap: 8px;
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid var(--cc-border);
}

.cc-add-bar input {
    flex: 1;
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius-sm);
    padding: 10px 14px;
    color: var(--cc-text-1);
    font-family: 'DM Sans', sans-serif;
    font-size: 14px;
    transition: border-color 0.2s;
}

.cc-add-bar input:focus {
    outline: none;
    border-color: var(--cc-indigo);
    box-shadow: 0 0 0 3px var(--cc-indigo-dim);
}

.cc-add-bar input::placeholder { color: var(--cc-text-3); }

.cc-add-bar select {
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius-sm);
    padding: 8px 10px;
    color: var(--cc-text-2);
    font-family: 'Space Mono', monospace;
    font-size: 10px;
}

.cc-add-btn {
    background: var(--cc-indigo);
    border: none;
    border-radius: var(--cc-radius-sm);
    color: white;
    font-size: 18px;
    width: 44px;
    min-height: 44px;
    cursor: pointer;
    transition: all 200ms cubic-bezier(0.25, 1, 0.5, 1);
    box-shadow: 0 2px 8px rgba(129, 140, 248, 0.25);
}

.cc-add-btn:hover {
    background: #6d78f0;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(129, 140, 248, 0.35);
}

/* ── Right Sidebar ── */

.cc-sidebar {
    display: flex;
    flex-direction: column;
    gap: 16px;
    overflow-y: auto;
    padding-left: 20px;
    border-left: 1px solid var(--cc-border);
}

.cc-sidebar::-webkit-scrollbar { width: 4px; }
.cc-sidebar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.06); border-radius: 2px; }

.cc-sidebar-label {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--cc-text-3);
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 10px;
}

/* ── Progress ── */
/* ── Helper Mascot ── */
.cc-helper {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px 0 8px;
}

#cc-mascot {
    filter: drop-shadow(0 4px 12px rgba(78, 204, 163, 0.25));
    transition: transform 300ms cubic-bezier(0.25, 1, 0.5, 1);
}

#cc-mascot:hover {
    transform: scale(1.08) rotate(-3deg);
}

.cc-helper-speech {
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    color: var(--cc-text-1);
    background: var(--cc-elevated);
    border: 1px solid var(--cc-accent);
    border-radius: 12px 12px 12px 4px;
    padding: 8px 14px;
    margin-top: 8px;
    max-width: 260px;
    text-align: center;

    box-shadow: 0 0 16px rgba(78, 204, 163, 0.15);
    animation: cc-speech-in 400ms cubic-bezier(0.25, 1, 0.5, 1) both;
    line-height: 1.4;
}

@keyframes cc-speech-in {
    from { opacity: 0; transform: translateY(6px) scale(0.95); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.cc-progress {
    padding: 16px;
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius);
    box-shadow: var(--cc-shadow-sm);
}

.cc-progress-label {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--cc-text-3);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 10px;
}

.cc-progress-bar {
    height: 6px;
    background: rgba(255,255,255,0.04);
    border-radius: 3px;
    overflow: hidden;
    margin-bottom: 8px;
}

.cc-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cc-accent), #6ee7c0);
    border-radius: 3px;
    transition: width 600ms cubic-bezier(0.25, 1, 0.5, 1), background 400ms;
    box-shadow: 0 0 14px var(--cc-accent-glow);
    position: relative;
}

.cc-progress-fill::after {
    content: '';
    position: absolute;
    right: 0;
    top: -4px;
    width: 8px;

    height: 14px;
    background: var(--cc-accent);
    border-radius: 2px;
    box-shadow: 0 0 10px var(--cc-accent), 0 0 20px var(--cc-accent-glow);
    opacity: 0.8;
}

.cc-progress-text {
    font-family: 'Rajdhani', sans-serif;
    font-size: 14px;
    font-weight: 500;
    color: var(--cc-text-2);
    font-variant-numeric: tabular-nums;
}

/* ── Streaks ── */
.cc-streaks {
    padding: 12px 0;
}

/* ── Deadlines ── */
.cc-deadlines {
    padding: 12px 0;
}

/* ── Chat ── */
.cc-chat {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 200px;
}

.cc-chat-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px;
    background: var(--cc-surface);
    border-radius: var(--cc-radius) var(--cc-radius) 0 0;
    border: 1px solid var(--cc-border);
    border-bottom: none;
    max-height: 300px;
}

.cc-chat-messages::-webkit-scrollbar { width: 4px; }
.cc-chat-messages::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.06); border-radius: 2px; }

.cc-chat-system {
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;

    color: var(--cc-text-3);
    padding: 6px 0;
    font-style: italic;
}

.cc-chat-user {
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    color: var(--cc-text-1);
    padding: 8px 12px;
    text-align: right;
    background: var(--cc-indigo-dim);
    border-radius: var(--cc-radius-sm);
    margin: 4px 0;
}

.cc-chat-assistant {
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    color: var(--cc-text-2);
    padding: 8px 0;
    line-height: 1.6;
}

.cc-chat-input {
    display: flex;
    border: 1px solid var(--cc-border);
    border-top: none;
    border-radius: 0 0 var(--cc-radius) var(--cc-radius);
    overflow: hidden;
}

.cc-chat-input input {
    flex: 1;
    background: var(--cc-elevated);
    border: none;
    padding: 12px 14px;
    color: var(--cc-text-1);
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
}

.cc-chat-input input:focus { outline: none; }
.cc-chat-input input::placeholder { color: var(--cc-text-3); }

.cc-chat-input button {
    background: var(--cc-indigo);
    border: none;
    color: white;
    padding: 0 16px;

    cursor: pointer;
    font-size: 12px;
    transition: background 0.15s;
}

.cc-chat-input button:hover { background: #6d78f0; }

/* ── Active Task (expanded) ── */
.cc-active-task {
    background: var(--cc-surface);
    border: 1px solid var(--cc-accent);
    border-radius: var(--cc-radius);
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 0 20px var(--cc-accent-glow), var(--cc-shadow-md);
    animation: cc-glow-pulse 3s ease-in-out infinite;
}

@keyframes cc-glow-pulse {
    0%, 100% { box-shadow: 0 0 16px var(--cc-accent-glow), var(--cc-shadow-md); }
    50% { box-shadow: 0 0 24px rgba(78, 204, 163, 0.35), var(--cc-shadow-md); }
}

.cc-active-title {
    font-family: 'Rajdhani', sans-serif;
    font-size: 20px;
    font-weight: 600;
    color: var(--cc-text-1);
    margin-bottom: 14px;
    letter-spacing: -0.3px;
}

.cc-timer {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
}

.cc-timer-display {
    font-family: 'Rajdhani', sans-serif;
    font-size: 36px;
    font-weight: 500;
    color: var(--cc-accent);
    letter-spacing: 3px;
    font-variant-numeric: tabular-nums;
    text-shadow: 0 0 20px var(--cc-accent-glow);
}

.cc-timer-bar {

    flex: 1;
    height: 4px;
    background: rgba(255,255,255,0.04);
    border-radius: 2px;
    overflow: hidden;
}

.cc-timer-fill {
    height: 100%;
    background: var(--cc-accent);
    border-radius: 2px;
    transition: width 1s linear;
    box-shadow: 0 0 6px var(--cc-accent-glow);
}

.cc-timer-display.cc-timer-overrun {
    color: #f5a623;
    text-shadow: 0 0 16px rgba(245,166,35,0.6);
    animation: cc-timer-pulse 1.6s ease-in-out infinite;
}

.cc-task-resurfaced {
    border-left: 3px solid #4ecca3;
    background: linear-gradient(90deg, rgba(78,204,163,0.06), transparent 40%);
}

.cc-resurfaced-info {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px 10px;
    margin-top: 8px;
    background: rgba(78,204,163,0.08);
    border-radius: 4px;
    font-size: 12px;
    color: #4ecca3;
    font-family: 'Space Mono', monospace;
}

.cc-resurfaced-actions {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
}

@keyframes cc-timer-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.55; }
}

.cc-active-actions {
    display: flex;
    gap: 8px;
    margin-top: 14px;
}

.cc-active-actions button {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    padding: 7px 16px;
    border: 1px solid var(--cc-border);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-text-2);
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

.cc-active-actions button:hover {
    background: var(--cc-raised);
    color: var(--cc-text-1);
}

.cc-active-actions .cc-done-btn {
    border-color: var(--cc-accent);
    color: var(--cc-accent);
}

.cc-active-actions .cc-done-btn:hover {
    background: var(--cc-accent-dim);
    box-shadow: 0 0 10px var(--cc-accent-glow);
}

.cc-active-actions .cc-blocked-btn {
    border-color: var(--cc-amber);
    color: var(--cc-amber);
}

.cc-active-actions .cc-blocked-btn:hover {
    background: var(--cc-amber-dim);
}

/* ── Animations ── */
@keyframes cc-spring {
    0%   { transform: scale(1); }
    40%  { transform: scale(0.93); }
    70%  { transform: scale(1.04); }
    100% { transform: scale(1); }
}

.cc-check-spring {
    animation: cc-spring 0.25s cubic-bezier(0.25, 1, 0.5, 1);
}

@keyframes cc-pulse {
    0%   { transform: scale(1); }
    50%  { transform: scale(1.06); box-shadow: 0 0 16px var(--cc-accent-glow); }
    100% { transform: scale(1); }
}

.cc-pulse {
    animation: cc-pulse 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}

@keyframes cc-slide-up {
    0%   { opacity: 1; transform: translateY(0); }
    100% { opacity: 0; transform: translateY(-16px); }
}

.cc-task-completing {
    animation: cc-slide-up 0.2s cubic-bezier(0.7, 0, 0.84, 0) forwards;
}

.cc-task-card.cc-task-focused {
    outline: 2px solid var(--cc-indigo);
    outline-offset: 2px;
}

/* Timer paused */
.cc-timer-paused .cc-timer-display {
    opacity: 0.4;
    text-shadow: none;
}

.cc-timer-paused .cc-timer-display::after {
    content: ' PAUSED';
    font-size: 12px;
    color: var(--cc-amber);
    letter-spacing: 2px;
}

/* ── Blocker Form ── */
.cc-blocker-form {
    background: var(--cc-raised);
    border: 1px solid var(--cc-amber);
    border-radius: var(--cc-radius);
    padding: 16px;
    margin-top: 14px;
    animation: cc-slide-down 0.2s cubic-bezier(0.25, 1, 0.5, 1);
    box-shadow: 0 0 12px var(--cc-amber-dim);

}

@keyframes cc-slide-down {
    0%   { opacity: 0; transform: translateY(-8px); }
    100% { opacity: 1; transform: translateY(0); }
}

.cc-blocker-title {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    color: var(--cc-amber);
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 12px;
}

.cc-blocker-types {
    display: flex;
    gap: 6px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}

.cc-blocker-type-btn {
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    padding: 6px 14px;
    border: 1px solid var(--cc-border);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-text-2);
    cursor: pointer;
    transition: all 0.15s;
}

.cc-blocker-type-btn:hover {
    border-color: var(--cc-amber);
    color: var(--cc-text-1);
}

.cc-blocker-type-btn.active {
    background: var(--cc-amber-dim);
    border-color: var(--cc-amber);
    color: var(--cc-amber);
}

.cc-blocker-fields {
    display: flex;
    flex-direction: column;
    gap: 8px;

    margin-bottom: 12px;
}

.cc-blocker-fields input,
.cc-blocker-fields select {
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius-sm);
    padding: 8px 12px;
    color: var(--cc-text-1);
    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
}

.cc-blocker-fields input:focus,
.cc-blocker-fields select:focus {
    outline: none;
    border-color: var(--cc-amber);
    box-shadow: 0 0 0 3px var(--cc-amber-dim);
}

.cc-blocker-fields input::placeholder { color: var(--cc-text-3); }

.cc-blocker-row {
    display: flex;
    gap: 8px;
}

.cc-blocker-row input { flex: 1; }

.cc-blocker-actions { display: flex; gap: 8px; }

.cc-blocker-submit {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    padding: 7px 18px;
    border: 1px solid var(--cc-amber);
    border-radius: 20px;
    background: var(--cc-amber-dim);
    color: var(--cc-amber);
    cursor: pointer;
    transition: all 0.15s;
}

.cc-blocker-submit:hover {
    background: rgba(245, 166, 35, 0.2);
}

.cc-blocker-cancel {
    font-family: 'Space Mono', monospace;

    font-size: 10px;
    padding: 7px 18px;
    border: 1px solid var(--cc-border);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-text-2);
    cursor: pointer;
}

.cc-blocker-cancel:hover { color: var(--cc-text-1); }

/* ── Waiting On cards ── */
.cc-task-card.cc-task-blocked .cc-blocker-info {
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--cc-border);
    font-family: 'DM Sans', sans-serif;
    font-size: 12px;
    color: var(--cc-amber);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.cc-blocker-resolve-btn {
    font-family: 'Space Mono', monospace;
    font-size: 10px;
    padding: 4px 12px;
    border: 1px solid var(--cc-accent);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-accent);
    cursor: pointer;
    transition: all 0.15s;
}

.cc-blocker-resolve-btn:hover {
    background: var(--cc-accent-dim);
    box-shadow: 0 0 8px var(--cc-accent-glow);
}

/* ── Reduced Motion ── */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

/* ── Urgency Tiers ── */

.cc-urgency-critical {
    border-left: 3px solid var(--cc-amber);
    box-shadow: 0 0 12px rgba(245, 166, 35, 0.2);
    animation: cc-pulse-amber 2s ease-in-out infinite;
}
.cc-urgency-high {
    border-left: 3px solid var(--cc-amber);
}
.cc-urgency-medium {
    border-left: 3px solid var(--cc-border-hover);
}
.cc-urgency-low {
    border-left: 3px solid transparent;
    opacity: 0.8;
}

@keyframes cc-pulse-amber {
    0%, 100% { box-shadow: 0 0 8px rgba(245, 166, 35, 0.15); }
    50% { box-shadow: 0 0 16px rgba(245, 166, 35, 0.3); }
}

/* ── Decisions Queue ── */
.cc-decision-card {
    border-left: 3px solid var(--cc-indigo);
    background: var(--cc-indigo-dim);
}
.cc-decision-options {
    display: flex;
    gap: 8px;
    margin-top: 8px;
    flex-wrap: wrap;
}
.cc-decision-opt {
    font-family: 'Space Mono', monospace;
    font-size: 11px;
    padding: 8px 16px;
    min-height: 36px;
    border: 1px solid var(--cc-indigo);
    border-radius: 20px;
    background: transparent;
    color: var(--cc-indigo);
    cursor: pointer;
    transition: all 200ms cubic-bezier(0.25, 1, 0.5, 1);
}
.cc-decision-opt:hover {
    background: var(--cc-indigo);
    color: white;
    box-shadow: 0 0 12px rgba(129, 140, 248, 0.3);
}
.cc-decision-input {

    font-family: 'DM Sans', sans-serif;
    font-size: 13px;
    padding: 8px 12px;
    min-height: 36px;
    flex: 1;
    min-width: 200px;
    background: var(--cc-surface);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-radius-sm);
    color: var(--cc-text-1);
    outline: none;
}
.cc-decision-input:focus {
    border-color: var(--cc-indigo);
    box-shadow: 0 0 0 3px var(--cc-indigo-dim);
}

